DO $$
DECLARE
  v_lib_id_29 uuid;
BEGIN
  SELECT id INTO v_lib_id_29 FROM quizzes WHERE title = 'سيرة الإمام جعفر الصادق (ع)' LIMIT 1;
  IF v_lib_id_29 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('سيرة الإمام جعفر الصادق (ع)', 'سلسلة مسابقات أهل البيت (ع)', '', 'standard', 'ar', true)
    RETURNING id INTO v_lib_id_29;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'من هو والد الإمام جعفر الصادق (ع)؟', '["الإمام علي زين العابدين (ع)","الإمام محمد الباقر (ع)","الإمام موسى الكاظم (ع)","زيد بن علي (ع)"]'::jsonb, 1, 15, 0, 'multi', 'أبوه الإمام محمد الباقر (ع).', 'الولادة والنشأة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'ما كنية الإمام جعفر الصادق (ع) الأشهر؟', '["أبو جعفر","أبو الحسن","أبو محمد","أبو عبد الله"]'::jsonb, 3, 15, 1, 'multi', 'كنيته الأشهر أبو عبد الله.', 'الولادة والنشأة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'من هي أم الإمام جعفر الصادق (ع)؟', '["أم فروة بنت القاسم","أم عبد الله بنت الحسن","حميدة المصفاة","نجمة خاتون"]'::jsonb, 0, 15, 2, 'multi', 'أمه أم فروة بنت القاسم بن محمد.', 'الولادة والنشأة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'في أي مدينة ولد الإمام الصادق (ع)؟', '["مكة المكرمة","الكوفة","المدينة المنورة","دمشق"]'::jsonb, 2, 15, 3, 'multi', 'كان مولده (ع) في المدينة المنورة.', 'الولادة والنشأة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'ما سنة ولادة الإمام الصادق (ع) عند الشيخ المفيد؟', '["80 هـ","95 هـ","83 هـ","100 هـ"]'::jsonb, 2, 15, 4, 'multi', 'ذكر المفيد أن ولادته كانت سنة 83 هـ.', 'الولادة والنشأة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'أي إمام سبق الصادق (ع) مباشرة في الإمامة؟', '["الإمام محمد الباقر (ع)","الإمام زين العابدين (ع)","الإمام موسى الكاظم (ع)","الإمام الحسن المجتبى (ع)"]'::jsonb, 0, 15, 5, 'multi', 'تولى الإمامة بعد أبيه الإمام الباقر (ع).', 'الإمامة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'بماذا أوصى الباقر (ع) ابنه جعفرًا عند قرب وفاته؟', '["أن يغادر المدينة","أن يعتزل تعليم الناس","أن يبيع كتبه","أن يحسن إلى أصحابه"]'::jsonb, 3, 20, 6, 'multi', 'أوصاه بأصحابه خيرًا، فوعد بتفقيههم.', 'الإمامة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'ماذا فعل الباقر (ع) حين سئل عمن يقوم بالأمر بعده؟', '["أشار إلى زيد بن علي","وضع يده على جعفر (ع)","كتب اسم إسماعيل","امتنع عن الجواب"]'::jsonb, 1, 20, 7, 'multi', 'وضع يده على جعفر وعيّنه قائمًا بالأمر بعده.', 'الإمامة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'لماذا أشهد الباقر (ع) جماعة على وصيته إلى جعفر؟', '["لتكون له حجة ولا يغلب","لتقسيم أموال التجارة","لتعيين والي المدينة","لإعلان رحلة إلى مكة"]'::jsonb, 0, 20, 8, 'multi', 'أراد أن تكون لجعفر حجة وألا يقال إنه لم يوص إليه.', 'الإمامة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'كم سنة دامت إمامة الإمام الصادق (ع)؟', '["19 سنة","25 سنة","34 سنة","40 سنة"]'::jsonb, 2, 15, 9, 'multi', 'دامت إمامته أربعًا وثلاثين سنة.', 'الإمامة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'كم راويًا جمع أصحاب الحديث ممن رووا عن الصادق (ع)؟', '["ألفان","أربعة آلاف","سبعمائة","عشرة آلاف"]'::jsonb, 1, 20, 10, 'multi', 'جمع أصحاب الحديث أسماء أربعة آلاف راوٍ عنه.', 'العلم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'كيف انتشر علم الإمام الصادق (ع) في الآفاق؟', '["بقي محصورًا في أسرته","اقتصر على رسائل سياسية","لم يروه إلا أهل المدينة","حمله الرواة إلى البلدان"]'::jsonb, 3, 20, 11, 'multi', 'حمل الرواة علومه إلى البلدان فانتشر ذكره.', 'العلم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'إلى من تنتهي سلسلة حديث الإمام الصادق (ع)؟', '["إلى علماء المدينة فقط","إلى كتب اليونان","إلى اجتهاده الشخصي","إلى رسول الله ثم الله"]'::jsonb, 3, 20, 12, 'multi', 'حديثه عن آبائه عن الرسول، وحديث الرسول قول الله.', 'العلم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'من الشاب الذي قدّمه الصادق (ع) لمناظرة الشامي؟', '["جابر الجعفي","هشام بن الحكم","المفضل بن عمر","أبان بن تغلب"]'::jsonb, 1, 15, 13, 'multi', 'قدّم هشام بن الحكم لمناظرة الشامي في الإمامة.', 'المناظرات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'كيف وصف الصادق (ع) نصرة هشام بن الحكم؟', '["يكثر السفر وحده","يجمع المال لأهله","ينصرنا بقلبه ولسانه ويده","يعتزل الخصومات كلها"]'::jsonb, 2, 20, 14, 'multi', 'قال عنه: ناصرنا بقلبه ولسانه ويده.', 'المناظرات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'أين كان مجلس مناظرة الشامي مع أصحاب الصادق (ع)؟', '["قرب حرم مكة","في مسجد الكوفة","في قصر دمشق","في مقبرة البقيع"]'::jsonb, 0, 20, 15, 'multi', 'كان المجلس في خيمة بطرف الحرم قبل الحج.', 'المناظرات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'بماذا استدل الصادق (ع) لأبي شاكر على حدوث العالم؟', '["بسفينة في البحر","ببيضة تنفلق عن طائر","بنخلة مثمرة","بحركة الشمس"]'::jsonb, 1, 20, 16, 'multi', 'استدل ببيضة محكمة تنفلق عن صورة طائر.', 'المناظرات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'ماذا قال الصادق (ع) عن دور الحواس في الاستدلال؟', '["هي أدلة ويحتاج الاستنباط إلى العقل","تكفي وحدها لكل معرفة","لا قيمة لها مطلقًا","تختص بمعرفة الأحكام"]'::jsonb, 0, 20, 17, 'multi', 'الحواس أدلة، ولا يتم الاستنباط بها من دون العقل.', 'العلم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'إلى كم أصل لخّص الصادق (ع) ما لا يسع الناس جهله؟', '["ثلاثة أصول","خمسة أصول","سبعة أصول","أربعة أصول"]'::jsonb, 3, 15, 18, 'multi', 'جمع ما لا يسع جهله في أربعة أصول.', 'الحكمة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'ما موقف الصادق (ع) من تشبيه الله بالأشياء؟', '["أجازه للتقريب","خصه بالأجرام","نفى أن يشبهه شيء","توقف فيه"]'::jsonb, 2, 15, 19, 'multi', 'نفى تشبيه الله بشيء أو تشبيه شيء به.', 'التوحيد');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'ما الذي عدّه الصادق (ع) غفلةً في موعظته؟', '["قلة السفر","تأخير التوبة","ترك التجارة","الصمت الطويل"]'::jsonb, 1, 15, 20, 'multi', 'عدّ تأخير التوبة اغترارًا وغفلة.', 'الحكمة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'ما الذي يكمل السعادة في حكمة الإمام الصادق (ع)؟', '["كثرة المال والولد","طول العمر والسفر","العزلة وترك العمل","اجتماع النية والقدرة والتوفيق والإصابة"]'::jsonb, 3, 20, 21, 'multi', 'تكتمل السعادة باجتماع النية والقدرة والتوفيق والإصابة.', 'الحكمة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'من الإمام الذي نص عليه الصادق (ع) من بعده؟', '["الإمام موسى الكاظم (ع)","إسماعيل بن جعفر","عبد الله الأفطح","محمد الديباج"]'::jsonb, 0, 15, 22, 'multi', 'نص على ابنه الإمام موسى الكاظم (ع).', 'الأسرة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'كم ولدًا يذكر المفيد للإمام الصادق (ع)؟', '["سبعة","اثنا عشر","عشرة","أربعة عشر"]'::jsonb, 2, 15, 23, 'multi', 'ذكر المفيد له عشرة أولاد: سبعة ذكور وثلاث إناث.', 'الأسرة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'في أي شهر توفي الإمام الصادق (ع) بحسب المفيد؟', '["محرم","رمضان","شوال","ذو الحجة"]'::jsonb, 2, 15, 24, 'multi', 'ذكر المفيد أن وفاته كانت في شهر شوال.', 'الاستشهاد');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'ما السنة الهجرية لوفاة الإمام الصادق (ع)؟', '["148 هـ","114 هـ","183 هـ","203 هـ"]'::jsonb, 0, 15, 25, 'multi', 'توفي سنة 148 هـ.', 'الاستشهاد');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'كم كان عمر الإمام الصادق (ع) عند وفاته؟', '["55 سنة","70 سنة","75 سنة","65 سنة"]'::jsonb, 3, 15, 26, 'multi', 'توفي وله خمس وستون سنة.', 'الاستشهاد');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_29, 'أين دفن الإمام جعفر الصادق (ع)؟', '["النجف","البقيع","الكاظمية","كربلاء"]'::jsonb, 1, 15, 27, 'multi', 'دفن في البقيع مع عدد من آبائه (ع).', 'الاستشهاد');
  END IF;
END $$;



DO $$
DECLARE
  v_lib_id_30 uuid;
BEGIN
  SELECT id INTO v_lib_id_30 FROM quizzes WHERE title = 'سيرة الإمام موسى الكاظم (ع)' LIMIT 1;
  IF v_lib_id_30 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('سيرة الإمام موسى الكاظم (ع)', 'سلسلة مسابقات أهل البيت (ع)', '', 'standard', 'ar', true)
    RETURNING id INTO v_lib_id_30;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_30, 'أين كانت ولادة الإمام موسى الكاظم (ع) بحسب الإرشاد؟', '["المدينة المنورة","الأبواء","مكة المكرمة","الكوفة"]'::jsonb, 1, 15, 0, 'multi', 'يذكر الشيخ المفيد أن مولده (ع) كان في الأبواء بين مكة والمدينة.', 'الولادة والنشأة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_30, 'في أي سنة وُلد الإمام الكاظم (ع) وفق رواية الإرشاد؟', '["120 هـ","132 هـ","148 هـ","128 هـ"]'::jsonb, 3, 15, 1, 'multi', 'نص الإرشاد على أن ولادته في الأبواء كانت سنة 128 هـ.', 'الولادة والنشأة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_30, 'من هو والد الإمام موسى الكاظم (ع)؟', '["الإمام جعفر الصادق (ع)","الإمام محمد الباقر (ع)","الإمام علي الرضا (ع)","إسماعيل بن جعفر"]'::jsonb, 0, 15, 2, 'multi', 'هو موسى بن الإمام جعفر الصادق (ع)، وقد نص أبوه على إمامته.', 'الولادة والنشأة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_30, 'ما اسم أم الإمام موسى الكاظم (ع) في الإرشاد؟', '["أم فروة بنت القاسم","نجمة","حميدة البربرية","سمانة"]'::jsonb, 2, 15, 3, 'multi', 'سمّى الشيخ المفيد أمه حميدة البربرية ووصفها بأنها أم ولد.', 'الولادة والنشأة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_30, 'ما الكنية الأشهر للإمام موسى بن جعفر (ع) في أبواب الكافي؟', '["أبو جعفر","أبو محمد","أبو الحسن","أبو عبد الله"]'::jsonb, 2, 15, 4, 'multi', 'يعبّر الكليني عنه في باب النص عليه بأبي الحسن موسى (ع).', 'الولادة والنشأة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_30, 'بعد أي إمام تولّى موسى الكاظم (ع) الإمامة؟', '["جعفر الصادق (ع)","محمد الباقر (ع)","علي الرضا (ع)","محمد الجواد (ع)"]'::jsonb, 0, 15, 5, 'multi', 'تولى الإمامة بعد وفاة أبيه الإمام جعفر الصادق (ع).', 'الإمامة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_30, 'من قال له الصادق (ع): «هو صاحبكم» مشيرًا إلى موسى (ع)؟', '["هشام بن الحكم","صفوان الجمال","علي بن يقطين","المفضّل بن عمر"]'::jsonb, 3, 20, 6, 'multi', 'سأل المفضّل عن صاحب الأمر بعد الصادق، فأشار إلى موسى (ع).', 'الإمامة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_30, 'ما علامة الإمام بعد الصادق (ع) في خبر فيض بن المختار؟', '["أنه أكبر أبنائه سنًا","أنه لا يلهو ولا يلعب","أنه يقيم في الكوفة","أنه يتولى القضاء"]'::jsonb, 1, 20, 7, 'multi', 'وجّه الصادق فيضًا إلى ملاحظة من لا يلهو ولا يلعب، فظهر موسى بهذه الصفة.', 'الإمامة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_30, 'بماذا وصف المفيد الإمام الكاظم (ع) بين أهل زمانه؟', '["أعبدهم وأسخاهم وأكرمهم نفسًا","أكثرهم اشتغالًا بالتجارة","أشهرهم بقيادة الجيوش","أوسعهم ولايةً في الدولة"]'::jsonb, 0, 20, 8, 'multi', 'عدّه المفيد أعبد أهل زمانه وأفقههم وأسخاهم كفًا وأكرمهم نفسًا.', 'الفضائل');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_30, 'ما الدعاء الذي كرره الإمام الكاظم (ع) في سجوده ليلًا؟', '["رب زدني مالًا وولدًا","اللهم انصرني بالسيف","عظم الذنب من عبدك فليحسن العفو من عندك","رب اجعلني ملكًا"]'::jsonb, 2, 20, 9, 'multi', 'نقل المفيد طول سجوده وتكراره طلب العفو بهذه العبارة.', 'العبادة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_30, 'كيف كان الكاظم (ع) يعامل من بلغه عنه أذى؟', '["يهجره دائمًا","يرسل إليه صرّة من المال","يرفع أمره إلى الوالي","يأمر بإبعاده"]'::jsonb, 1, 15, 10, 'multi', 'كان إذا بلغه عن رجل ما يؤذيه بعث إليه بصرة من المال.', 'الأخلاق');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_30, 'ما مقدار صرر الإمام الكاظم (ع) المشهورة لأهل المدينة؟', '["من دينار إلى 5 دنانير","2000 دينار دائمًا","10 دراهم فقط","من 200 إلى 300 دينار"]'::jsonb, 3, 20, 11, 'multi', 'ذكر المفيد أن صراره كانت تتراوح بين مئتي دينار وثلاثمئة.', 'الكرم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
