    VALUES (v_lib_id_35, 'ما الاسم الأشهر لأم الإمام المهدي (عج) في روايات ولادته؟', '["حكيمة","حديث","نرجس","سمانة"]'::jsonb, 2, 20, 3, 'multi', 'اشتهرت أم الإمام المهدي في روايات الولادة باسم نرجس، مع ورود أسماء أخرى لها.', 'الولادة والنشأة');
