    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_35, 'ماذا فعل الإمام العسكري (ع) لإثبات ولادة ابنه لبعض ثقاته؟', '["أراه لعدد من أصحابه الخواص","أعلنه على منبر بغداد","أرسله إلى المدينة علنًا","سجله لدى ديوان الخلافة"]'::jsonb, 0, 20, 8, 'multi', 'عرض الإمام العسكري ابنه على جماعة مختارة من أصحابه وعرّفهم إمامهم بعده.', 'الولادة والنشأة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
