    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_35, 'كم نائبًا خاصًا تعاقب في الغيبة الصغرى؟', '["ثلاثة","خمسة","سبعة","أربعة"]'::jsonb, 3, 15, 11, 'multi', 'تعاقب في السفارة الخاصة عثمان، ثم محمد، ثم الحسين بن روح، ثم علي السمري.', 'النواب الأربعة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_35, 'من كان أول النواب الأربعة؟', '["محمد بن عثمان العمري","الحسين بن روح النوبختي","علي بن محمد السمري","عثمان بن سعيد العمري"]'::jsonb, 3, 15, 12, 'multi', 'كان عثمان بن سعيد أول سفير للإمام المهدي في الغيبة الصغرى.', 'النواب الأربعة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_35, 'أي حرفة اتخذها عثمان بن سعيد ستارًا لخدمته ونقل الأموال؟', '["نسخ الكتب","بيع السمن","صياغة الفضة","تجارة الورق"]'::jsonb, 1, 20, 13, 'multi', 'عُرف عثمان بالسمّان، وكان يجعل الأموال في أوعية السمن ويوصلها سترًا للأمر.', 'النواب الأربعة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_35, 'من تولى النيابة الخاصة بعد عثمان بن سعيد؟', '["الحسين بن روح","علي بن محمد السمري","ابنه محمد بن عثمان","أحمد بن إسحاق القمي"]'::jsonb, 2, 15, 14, 'multi', 'تولى محمد بن عثمان العمري السفارة بعد وفاة أبيه عثمان بن سعيد.', 'النواب الأربعة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_35, 'من كان ثالث النواب الأربعة؟', '["الحسين بن روح النوبختي","عثمان بن سعيد العمري","محمد بن عثمان العمري","علي بن محمد السمري"]'::jsonb, 0, 15, 15, 'multi', 'نص محمد بن عثمان على الحسين بن روح، فكان السفير الثالث.', 'النواب الأربعة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_35, 'من كان آخر النواب الخاصين في الغيبة الصغرى؟', '["الحسين بن روح النوبختي","علي بن محمد السمري","محمد بن عثمان العمري","عثمان بن سعيد العمري"]'::jsonb, 1, 15, 16, 'multi', 'كان علي بن محمد السمري رابع السفراء وآخرهم.', 'النواب الأربعة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_35, 'ما المهمة الأساسية للنواب الخاصين؟', '["إيصال التوقيعات وشؤون الشيعة بين الإمام وأتباعه","تولي منصب الخلافة العباسية","قيادة جيش ظاهر في سامراء","تأسيس مذهب فقهي جديد"]'::jsonb, 0, 25, 17, 'multi', 'كان السفراء وسطاء موثوقين في المكاتبات والتوقيعات والأموال والمسائل.', 'الغيبة الصغرى');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_35, 'ما اسم الرسائل الصادرة عن الإمام المهدي (عج) إلى وكلائه وشيعته؟', '["الصحائف","المقامات","المعلقات","التوقيعات"]'::jsonb, 3, 20, 18, 'multi', 'تسمّي المصادر كتب الإمام وأجوبته الخارجة إلى نوابه وشيعته «التوقيعات».', 'الغيبة الصغرى');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_35, 'ما الترتيب الصحيح للنواب الأربعة؟', '["محمد، عثمان، السمري، الحسين بن روح","الحسين بن روح، عثمان، محمد، السمري","عثمان، محمد، الحسين بن روح، السمري","عثمان، الحسين بن روح، محمد، السمري"]'::jsonb, 2, 25, 19, 'multi', 'الترتيب هو عثمان بن سعيد، محمد بن عثمان، الحسين بن روح، ثم علي السمري.', 'النواب الأربعة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_35, 'ماذا أمر التوقيع الأخير علي بن محمد السمري بشأن خليفته؟', '["أن يعيّن ابنه سفيرًا","ألا يوصي إلى أحد بعده","أن يعيد السفارة للحسين بن روح","أن ينقل السفارة إلى سامراء"]'::jsonb, 1, 25, 20, 'multi', 'أخبر التوقيع السمري بقرب وفاته وأمره ألا يعهد إلى أحد؛ فقد وقعت الغيبة التامة.', 'بداية الغيبة الكبرى');
