    VALUES (v_lib_id_35, 'في أي سنة انتهت الغيبة الصغرى وبدأت الغيبة الكبرى؟', '["260هـ","305هـ","350هـ","329هـ"]'::jsonb, 3, 15, 21, 'multi', 'بوفاة السفير الرابع علي السمري سنة 329هـ انتهت السفارة الخاصة وبدأت الغيبة الكبرى.', 'بداية الغيبة الكبرى');
  END IF;
END $$;



DO $$
DECLARE
  v_lib_id_36 uuid;
BEGIN
  SELECT id INTO v_lib_id_36 FROM quizzes WHERE title = 'تضاريس وظواهر طبيعية فريدة' LIMIT 1;
  IF v_lib_id_36 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('تضاريس وظواهر طبيعية فريدة', 'جغرافيا', '', 'medium', 'ar', true)
    RETURNING id INTO v_lib_id_36;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'أي عملية جيومورفولوجية أنشأت الأعمدة السداسية الشهيرة في ممر العمالقة بأيرلندا الشمالية؟', '["ترسيب أملاح بحرية متعاقبة","تبريد حمم بازلتية وانكماشها","نحت الحجر الجيري بمياه جوفية","ضغط كثبان رملية متحجرة"]'::jsonb, 1, 30, 0, 'multi', 'تكوّنت الأعمدة عندما بردت تدفقات بازلتية قديمة فانكمشت وتشقق سطحها إلى مضلعات، يغلب عليها الشكل السداسي. لذلك فهي فواصل تبريد وليست نتاج إذابة كارستية أو ترسيب ملحي.', 'تضاريس بركانية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'لماذا يبدو نهر كانيو كريستاليس في كولومبيا متعدد الألوان خلال موسم محدد؟', '["تذوب فيه معادن نحاسية من مناجم قريبة","تعكس مياهه ألوان الطيور المهاجرة","تتلون نباتات مائية مستوطنة مع ملاءمة الضوء ومستوى الماء","تطلق ينابيع حارة أصباغًا كبريتية"]'::jsonb, 2, 30, 1, 'multi', 'يرتبط اللون الأحمر خصوصًا بالنبات المائي Macarenia clavigera الذي تظهر ألوانه حين يتوازن عمق الماء والضوء بين موسمي المطر والجفاف؛ وتضيف الصخور والرمال والطحالب ألوانًا أخرى.', 'أنهار وظواهر حيوية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'ما العامل الرئيس الذي حافظ على ملوحة البحر الميت الشديدة مقارنة بمعظم البحيرات؟', '["اتصاله المباشر ببحر شديد الملوحة","كونه حوضًا مغلقًا يفقد الماء أساسًا بالتبخر","ذوبان جليد غني بالأملاح فيه سنويًا","ارتفاعه الكبير الذي يمنع هطول المطر"]'::jsonb, 1, 30, 2, 'multi', 'البحر الميت بحيرة نهائية بلا مخرج نهري إلى البحر. يزيل التبخر الماء ويترك الأملاح الذائبة تتراكم، كما أن موقعه منخفض لا مرتفع.', 'بحيرات ملحية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'أي وصف يفسر تكوّن الأخاديد العميقة مثل غراند كانيون على نحو أدق؟', '["انهيار سقف كهف واحد ضخم","شق فتحه اصطدام نيزك حديث","حتّ نهري طويل ترافق مع رفع إقليمي لهضبة كولورادو","أخدود حفره نهر جليدي ساحلي"]'::jsonb, 2, 30, 3, 'multi', 'عمّق نهر كولورادو وروافده الوادي مع ارتفاع هضبة كولورادو، فكشفت التعرية طبقات صخرية تمتد إلى أزمنة سحيقة. لا يمثل الوادي فوهة صدم ولا كهفًا منهارًا.', 'أودية وأخاديد');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'تتكون صواعد الكهوف الجيرية عادةً عندما يحدث ماذا؟', '["تتجمد مياه جوفية صاعدة داخل السقف","تضغط حركة الصفائح الطين إلى أعلى","تنحت الرياح أعمدة من الرمال المتماسكة","تترسب كربونات الكالسيوم من قطرات تسقط على أرضية الكهف"]'::jsonb, 3, 30, 4, 'multi', 'تفقد القطرات بعض ثاني أكسيد الكربون بعد وصولها إلى الكهف، فتترسب كربونات الكالسيوم على الأرض وتنمو الصواعد إلى أعلى؛ أما الهوابط فتنمو من السقف.', 'كارست وكهوف');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'ما الذي يميز دلتا داخلية مثل دلتا أوكافانغو في بوتسوانا عن الدلتا الساحلية المعتادة؟', '["تتكون حصرًا من حمم تحت الماء","ترتفع فوق خط تقسيم المياه","يتبدد النهر في حوض قاري ولا يصل إلى المحيط","لا تحتوي أي رواسب نهرية"]'::jsonb, 2, 30, 5, 'multi', 'تصب مياه أوكافانغو داخل حوض كالاهاري المغلق، فتنتشر في شبكة مستنقعات وقنوات ثم تضيع بالتبخر والنتح والتسرب بدل بلوغ البحر.', 'أنهار ودلتات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'في أي بيئة تتشكل التربة المضلعة والدوائر الحجرية الطبيعية المرتبطة بظاهرة الأرض المنمطة؟', '["الغابات المدارية عديمة التباين الحراري","قيعان المحيط العميقة قرب الفتحات الحارة","الصحارى الحارة التي لا تتجمد","بيئات التجمد والذوبان المتكرر في الأقاليم الباردة"]'::jsonb, 3, 30, 6, 'multi', 'تدفع دورات التجمد والذوبان الحبيبات وتفرزها بحسب الحجم، فتتشكل مضلعات ودوائر وخطوط حجرية في البيئات المحيطة بالجليدية.', 'تضاريس جليدية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'لماذا تتخذ بحيرات كثيرة داخل الفوهات البركانية شكلًا دائريًا أو شبه دائري؟', '["لأن الأنهار ترسم دائمًا دوائر عند منابعها","لأن الماء يملأ منخفضًا أنشأه انفجار أو انهيار بركاني","لأن الرياح تدور في نصف الكرة الشمالي","لأن الجليد البحري يحفر حلقات منتظمة"]'::jsonb, 1, 30, 7, 'multi', 'قد يخلّف الثوران فوهة، أو ينهار سقف حجرة الصهارة ليكوّن كالديرا؛ وعندما تتجمع المياه داخل ذلك المنخفض تحاكي البحيرة حدوده الدائرية نسبيًا.', 'بحيرات بركانية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'أي آلية تجعل الكثيب الهلالي المعروف بالبرخان يتحرك تدريجيًا؟', '["يدفع المد البحري الكثيب كله من أسفله","تتمدد حبات الرمل ليلًا فتنزلق شرقًا","ترفع المياه الجوفية الكثيب ككتلة واحدة","تنقل الرياح الرمل صعودًا على الجانب المواجه ثم ينهال خلف القمة"]'::jsonb, 3, 30, 8, 'multi', 'تقفز الحبات وتتدحرج على المنحدر المواجه للريح، ثم تعبر القمة وتنهال على وجه الانزلاق، فيتقدم الكثيب باتجاه هبوب الريح وتبرز قرناه إلى الأمام.', 'تضاريس ريحية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'ما التفسير الجيولوجي المقبول لوجود أحافير بحرية في صخور عالية بجبال الهيمالايا؟', '["نقلتها طيور بحرية إلى القمم الحديثة","غطى مد يومي قمم الجبال قبل قرون","ارتفعت رواسب بحر تيثس القديم أثناء تصادم الهند بأوراسيا","قذفتها براكين المحيط الهندي إلى الجبال"]'::jsonb, 2, 35, 9, 'multi', 'ترسبت المواد في بحر تيثس بين الكتلتين القاريتين، ثم طُويت وارتفعت عندما اصطدمت الصفيحة الهندية بأوراسيا؛ لذا أصبحت الصخور الرسوبية البحرية جزءًا من أعلى سلسلة جبلية.', 'جبال وصفائح');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'في الحواف الجليدية، ما الفرق الأدق بين الفيورد والوادي النهري العادي؟', '["الفيورد قناة حفرتها الحمم ولها مقطع V","الفيورد بحيرة مغلقة لا تتصل بالبحر","الفيورد أخدود ريحي يوجد فقط في الصحارى","الفيورد وادٍ جليدي عميق غمره البحر وله مقطع على هيئة U"]'::jsonb, 3, 35, 10, 'multi', 'تحفر الأنهار الجليدية أودية عريضة شديدة الجوانب ذات مقطع U، ثم يغمر البحر الجزء السفلي بعد تراجع الجليد أو تغير مستوى البحر، فينشأ الفيورد.', 'سواحل جليدية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'أي اقتران بين تضريس كارستي وآلية تكوّنه صحيح؟', '["الدولين: إذابة صخر قابل للذوبان وانهيار أو هبوط السطح","المورين: ترسيب كربونات من مياه الكهوف","الياردانغ: إذابة الجبس بالماء الجوفي فقط","الإسكر: انهيار سقف حجرة صهارية"]'::jsonb, 0, 40, 11, 'multi', 'الدولين منخفض كارستي يتشكل بالإذابة أو انهيار تجاويف في الحجر الجيري ونحوه. المورين ركام جليدي، والياردانغ نحت ريحي، والإسكر راسب نهري جليدي.', 'كارست وكهوف');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'ما الشرط التكتوني الأكثر ارتباطًا بتكوين وادٍ صدعي قاري مثل أجزاء من صدع شرق أفريقيا؟', '["تمدد القشرة وهبوط كتل بين صدوع عادية","انضغاط القشرة وتراكب الدسرات","انزلاق أفقي محض بلا تمدد","اصطدام صفيحتين محيطيتين فقط"]'::jsonb, 0, 40, 12, 'multi', 'حين تتمدد القشرة القارية ترقّ وتتشقق بصدوع عادية، وقد تهبط كتلة وسطية لتكوّن غورًا أو واديًا صدعيًا. أما الانضغاط فيبني عادة أحزمة طي ودسر.', 'تكتونية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'تتكون بحيرات المنعطف المقطوع (قوس الثور) عندما يحدث أي تسلسل؟', '["ينهار بركان دائري ثم يملأ المطر فوهته","يضيق عنق منعطف نهري ثم يقطعه النهر وتسد الرواسب القناة القديمة","يسد ركام جليدي خليجًا بحريًا","تذيب المياه الجوفية قبة ملحية كاملة"]'::jsonb, 1, 40, 13, 'multi', 'تزيد التعرية على الضفتين الخارجيتين والترسيب داخليًا من تقارب عنق المنعطف؛ وعند الفيضان قد يفتح النهر مسارًا أقصر، ثم تعزل الرواسب الحلقة القديمة كبحيرة هلالية.', 'أنهار');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'لماذا يمكن أن يكون قاع وادٍ جاف في القارة القطبية الجنوبية شبه خالٍ من الجليد رغم البرودة الشديدة؟', '["تسخن تيارات محيطية القاع فوق نقطة الغليان","تغطي الحمم الحديثة الوادي كل شتاء","تمنع الملوحة تجمد أي هطول جوي","تحد الرياح الهابطة الجافة من تراكم الثلج وتسرّع التسامي"]'::jsonb, 3, 40, 14, 'multi', 'تندفع رياح كاتاباتية باردة وكثيفة من المرتفعات، وتسخن بالانضغاط أثناء هبوطها وتزيل الثلج بالتسامي والنقل، بينما تحجب الجبال قدرًا كبيرًا من الهطول.', 'ظواهر قطبية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'أي تفسير يطابق تكوّن بحيرة توبا الهائلة في سومطرة؟', '["امتلأت كالديرا نتجت من ثوران انفجاري ضخم وانهيار السقف","سد نهر جليدي واديًا استوائيًا","كوّن اصطدام قاري حوضًا أماميًا ضحلًا","قطع منعطف نهري واسع عن مجراه"]'::jsonb, 0, 40, 15, 'multi', 'بحيرة توبا تشغل كالديرا تكونت خلال ثوران هائل قبل نحو 74 ألف سنة؛ أُفرغ مقدار كبير من الصهارة فانهار الجزء العلوي من النظام البركاني.', 'براكين وكالديرات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'ما الذي يجعل السهل الملحي سالار دي أويوني في بوليفيا يعمل كمرآة واسعة أحيانًا؟', '["تذوب بلورات الملح فتصبح زجاجًا دائمًا","تغطي طبقة رقيقة ساكنة من الماء سطح الملح شديد الاستواء","تكسو الطحالب الفضية سطحه في الشتاء","تترسب طبقة سنوية من الجليد البحري"]'::jsonb, 1, 40, 16, 'multi', 'خلال موسم الأمطار يمكن لماء ضحل أن يغطي القشرة الملحية المسطحة جدًا، فينشئ سطحًا عاكسًا متصلًا. الظاهرة انعكاس مائي وليست تحول الملح إلى زجاج.', 'سبخات وسهول ملحية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'أي ترتيب يمثل انتقال الرواسب الصحيح في نظام نهر جليدي ثم ذوبانه؟', '["يحمل الجليد ركامًا غير مفروز، بينما تفرز مياه الذوبان الحبيبات في رواسب طبقية","يفرز الجليد الحبيبات بدقة، بينما يترك ماء الذوبان ركامًا غير مفروز","كلاهما يترك رواسب ملحية فقط","لا ينقل الجليد إلا الطين ولا ينقل الماء الحصى"]'::jsonb, 0, 45, 17, 'multi', 'الركام الجليدي المباشر (التيل) خليط غير مفروز من أحجام متعددة، أما الجداول الجليدية فتفرز المواد بحسب سرعة الجريان وتبني رواسب طبقية مثل السهول الغسلية والإسكرات.', 'رواسب جليدية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'لماذا تُعد بحيرة بايكال مثالًا لبحيرة صدعية عميقة لا لحوض حفَرته الأنهار الجليدية أساسًا؟', '["تقع داخل فوهة نيزكية دائرية","نشأت خلف ركام جليدي طرفي حديث","تشغل منطقة قارية متمددة تهبط بين صدوع نشطة","عزلها حاجز رملي عن المحيط"]'::jsonb, 2, 45, 18, 'multi', 'يقع حوض بايكال ضمن نظام صدعي قاري نشط؛ أدى التمدد والهبوط الطويلان إلى حوض شديد العمق تراكمت فيه سماكات كبيرة من الرواسب.', 'بحيرات صدعية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'في جزيرة بركانية محيطية، ما الدليل التضاريسي الأكثر اتساقًا مع انتقال الصفيحة فوق بقعة ساخنة شبه ثابتة؟', '["سلسلة براكين يزداد عمرها تدريجيًا بعيدًا عن البركان النشط","حلقة جبال متساوية العمر حول قارة","أخاديد نهرية تتجه كلها شمالًا","كثبان تتناقص حجومها نحو الساحل"]'::jsonb, 0, 45, 19, 'multi', 'تتكون براكين جديدة فوق مصدر الصهارة، ثم تحملها حركة الصفيحة بعيدًا فتخمد وتتعرض للتعرية؛ لذا يسجل تدرج الأعمار اتجاه حركة الصفيحة، كما في سلسلة هاواي–الإمبراطور.', 'بقع ساخنة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'ما الآلية التي تنشئ المدرجات النهرية المتعاقبة على جانبي وادٍ؟', '["ترتفع أمواج المد فتقص درجات متساوية داخل اليابسة","تترسب الحمم دوريًا داخل النهر فقط","يتحول النهر من بناء سهل فيضي إلى الحت الرأسي، فيترك أسطح الفيضان القديمة أعلى المجرى","تذيب المياه الجوفية طبقات أفقية من قاع الوادي"]'::jsonb, 2, 45, 20, 'multi', 'عندما ينخفض مستوى الأساس أو ترتفع اليابسة أو يتغير التصريف، يعمّق النهر مجراه. تبقى أجزاء من السهل الفيضي الأقدم معلقة كمدرجات تسجل مراحل سابقة للوادي.', 'جيومورفولوجيا نهرية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'أي وصف يميز الينابيع الحارة عن السخانات النافورية (الغيْزرات) من حيث آلية الثوران؟', '["كل ينبوع حار يثور دوريًا بالضرورة","لا يسخن الغيزر إلا من أشعة الشمس","ينشأ الغيزر فقط عند التقاء نهرين جليديين","يحتاج الغيزر إلى شبكة قنوات تقيد الحمل الحراري فتسمح بتراكم الضغط ثم التفريغ الدوري"]'::jsonb, 3, 45, 21, 'multi', 'يتطلب الغيزر حرارة وماءً ونظام قنوات مناسبًا؛ يرفع الحبس ضغط الماء فيبقى فائق السخونة، ثم يؤدي بدء الغليان وانخفاض الضغط إلى تفريغ انفجاري متكرر. الينبوع الحار المفتوح يدور ماؤه عادة بلا ثوران.', 'حرارة أرضية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'ما الذي يفسر بقاء صخور متحركة في مضمار السباق بوادي الموت وتركها مسارات طويلة؟', '["مجال مغناطيسي يسحب الصخور الحديدية","صفائح جليد رقيقة تتكسر وتدفعها رياح خفيفة فوق طين مبلل","زلازل يومية تقذفها بالتتابع","سيول عميقة تحملها وهي طافية"]'::jsonb, 1, 45, 22, 'multi', 'كشفت المراقبة أن البرك الضحلة تتجمد ليلًا حول الصخور، ثم تتكسر ألواح الجليد عند الذوبان وتدفعها الرياح ببطء فوق السطح الطيني الزلق، فتنقش المسارات.', 'ظواهر صحراوية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'أي تسلسل يصف نشأة الجزيرة الحاجزية الساحلية على نحو أدق؟', '["تبني الأنهار الجليدية جدارًا صخريًا عموديًا في المدار","ينهار بركان خطي وتملأه مياه عذبة","تعيد الأمواج والتيارات الساحلية توزيع الرمل في شريط موازٍ للشاطئ يفصله خليج أو بحيرة ضحلة","تذيب الأمواج الحجر الجيري تحت قارة فتفصلها كاملة"]'::jsonb, 2, 45, 23, 'multi', 'الجزر الحاجزية أجسام رملية طويلة موازية للساحل تفصلها عنه بحيرات أو خلجان ضحلة، وتعيد الأمواج والتيارات والانجراف الساحلي تشكيلها باستمرار، لذلك فهي تضاريس ديناميكية.', 'تضاريس ساحلية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_36, 'لماذا تظهر شلالات الترافرتين على هيئة مصاطب متتابعة في مواقع مثل باموق قلعة؟', '["تفقد المياه الغنية بالبيكربونات ثاني أكسيد الكربون فتترسب كربونات الكالسيوم عند الحواف","تتجمد الحمم البازلتية في طبقات بيضاء","تنحت الرياح درجات في الجرانيت ثم تملؤها الأمطار","تضغط الصفائح رواسب الملح إلى سلالم منتظمة"]'::jsonb, 0, 45, 24, 'multi', 'تصعد مياه حرارية محملة بالكالسيوم والبيكربونات، وعند انكشافها يخرج ثاني أكسيد الكربون فتترسب كربونات الكالسيوم كترافرتين. يتركز الترسيب عند الحواف فيبني أحواضًا ومصاطب بيضاء.', 'ترسيب كيميائي');
  END IF;
END $$;



DO $$
DECLARE
  v_lib_id_37 uuid;
BEGIN
  SELECT id INTO v_lib_id_37 FROM quizzes WHERE title = 'حدود سياسية وجغرافيا تاريخية' LIMIT 1;
  IF v_lib_id_37 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('حدود سياسية وجغرافيا تاريخية', 'جغرافيا', '', 'high', 'ar', true)
    RETURNING id INTO v_lib_id_37;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'وفق الحدود البرية المعترف بها دوليًا في عام 2026، أي دولتين تفصل بينهما حدود تمتد على خط عرض 49° شمالًا لمسافة كبيرة، لكنها لا تلتزم به كاملًا؟', '["الولايات المتحدة والمكسيك","كندا والولايات المتحدة","النرويج والسويد","روسيا وكازاخستان"]'::jsonb, 1, 35, 0, 'multi', 'رسمت اتفاقية 1818 جانبًا مهمًا من الحدود الأمريكية الكندية على خط العرض 49 من بحيرة الغابات إلى جبال روكي، ثم وُسع المسار غربًا باتفاقية أوريغون عام 1846. لكن الحدود تنحرف عنه حول البحيرات العظمى وألاسكا ومناطق أخرى، لذلك ليست خطًا موازيًا كاملًا.', 'حدود فلكية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'أي دولة تُحاط أراضيها البرية بالكامل بدولة جنوب أفريقيا، وفق الوضع السياسي في عام 2026؟', '["ليسوتو","إسواتيني","بوتسوانا","ناميبيا"]'::jsonb, 0, 30, 1, 'multi', 'ليسوتو دولة جيبية ذات سيادة محاطة بجنوب أفريقيا من جميع الجهات. أما إسواتيني فتجاور جنوب أفريقيا وموزمبيق، في حين تمتلك بوتسوانا وناميبيا حدودًا مع عدة دول.', 'الدول الجيبية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'أي إقليم روسي يقع منفصلًا عن بقية أراضي روسيا بين بولندا وليتوانيا على بحر البلطيق في عام 2026؟', '["كاريليا","تشوكوتكا","كالينينغراد","داغستان"]'::jsonb, 2, 30, 2, 'multi', 'أوبلاست كالينينغراد جزء من روسيا لكنه منفصل جغرافيًا عن كتلتها الرئيسة، وتحده بولندا وليتوانيا وبحر البلطيق. انتقل القسم الشمالي من بروسيا الشرقية إلى الاتحاد السوفيتي بعد الحرب العالمية الثانية.', 'أقاليم منفصلة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'أي مضيق يفصل في الوقت نفسه بين إسبانيا والمغرب، وبين المحيط الأطلسي والبحر المتوسط؟', '["مضيق جبل طارق","مضيق البوسفور","مضيق أوترانتو","مضيق مسينا"]'::jsonb, 0, 30, 3, 'multi', 'يقع مضيق جبل طارق بين جنوب إسبانيا وشمال المغرب، ويصل الأطلسي بالمتوسط. وهو لذلك حاجز مائي بين دولتين وقارتين وممر بحري بين حوضين.', 'حدود بحرية ومضائق');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'أي معاهدة أنهت الحرب المكسيكية الأمريكية سنة 1848 ونقلت إلى الولايات المتحدة مساحة واسعة شملت كاليفورنيا الحالية؟', '["معاهدة آدامز–أونيس","معاهدة أوريغون","معاهدة باريس 1783","معاهدة غوادالوبي هيدالغو"]'::jsonb, 3, 35, 4, 'multi', 'أنهت معاهدة غوادالوبي هيدالغو الحرب عام 1848، واعترفت المكسيك بضم تكساس وتنازلت عن رقعة شاسعة في الغرب والشمال الغربي. أما شراء غادسدن فجاء لاحقًا عام 1853 واستكمل جزءًا من الحد الجنوبي.', 'معاهدات وحدود تاريخية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'عند استقلال الهند البريطانية سنة 1947، ما الكيانان السياديان اللذان أنشأهما قانون استقلال الهند البريطاني؟', '["الهند وبنغلادش","باكستان وبنغلادش","الهند وسريلانكا","الهند وباكستان"]'::jsonb, 3, 35, 5, 'multi', 'أنشأ قانون 1947 دومينيوني الهند وباكستان. وكانت باكستان تتألف من جناحين غربي وشرقي تفصل بينهما الهند؛ استقل الجناح الشرقي باسم بنغلادش عام 1971.', 'تقسيم الدول');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'أي خط هدنة رُسم سنة 1949 بين إسرائيل والأردن، واشتهر باسم «الخط الأخضر»؟', '["خط سايكس–بيكو","خط الهدنة المحدد على خرائط اتفاقيات رودس","خط بارليف","خط الهدنة بين لبنان وسوريا"]'::jsonb, 1, 35, 6, 'multi', 'نشأ الخط الأخضر من خطوط الهدنة لعام 1949، وسمي بلون القلم المستخدم على الخرائط. نصت اتفاقية الهدنة الأردنية الإسرائيلية على أن الخطوط لا تمس التسويات الإقليمية أو الحدود النهائية، لذا هو خط هدنة تاريخي لا معاهدة حدود نهائية بذاته.', 'خطوط هدنة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'أي خط عرض اعتمدته الهدنة الكورية سنة 1953 بوصفه الحد الفعلي النهائي؟', '["خط العرض 38 كاملًا","خط العرض 39 كاملًا","لم تعتمد خط عرض ثابتًا؛ أنشأت خط ترسيم عسكريًا وفق مواقع الجبهات","خط العرض 37 كاملًا"]'::jsonb, 2, 35, 7, 'multi', 'كان خط العرض 38 أساس التقسيم الأول بعد الحرب العالمية الثانية، لكن اتفاقية هدنة 1953 رسمت خط الترسيم العسكري قرب مواقع القتال، تحيط به منطقة منزوعة السلاح. لذلك لا يطابق الحد الفعلي خط 38 على امتداده.', 'حدود عسكرية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'أي دولة أفريقية نالت استقلالها سنة 1993 بعد استفتاء، فأصبحت إثيوبيا دولة حبيسة؟', '["إريتريا","جيبوتي","جنوب السودان","الصومال"]'::jsonb, 0, 30, 8, 'multi', 'أفضى استفتاء أشرفت عليه الأمم المتحدة إلى استقلال إريتريا عام 1993. وبخروج الساحل الإريتري من السيادة الإثيوبية فقدت إثيوبيا منفذها إلى البحر الأحمر وأصبحت حبيسة.', 'استقلال وتغير حدود');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'أي نهر يشكل أجزاء مهمة من الحدود الحالية بين ألمانيا وبولندا، إلى جانب رافده نيسه اللوساتية؟', '["الأودر","الإلبه","الراين","الدانوب"]'::jsonb, 0, 30, 9, 'multi', 'يمثل خط أودر–نيسه أساس الحدود الألمانية البولندية التي تشكلت بعد الحرب العالمية الثانية وأكدتها ألمانيا الموحدة وبولندا بمعاهدة عام 1990. الأودر هو النهر الرئيس في هذا الوصف، والنيسه اللوساتية رافده الحدودي.', 'حدود نهرية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'في تسوية مؤتمر فيينا سنة 1815، أُنشئت «المملكة المتحدة للأراضي المنخفضة» أساسًا بضم أي منطقتين؟', '["هولندا والدنمارك","بلجيكا ولوكسمبورغ فقط","المقاطعات الهولندية شمالًا والأراضي البلجيكية جنوبًا","هولندا وهانوفر"]'::jsonb, 2, 45, 10, 'multi', 'جمع ترتيب ما بعد نابليون المقاطعات الهولندية في الشمال بالأراضي البلجيكية السابقة في الجنوب ضمن مملكة واحدة لتكون حاجزًا شمال فرنسا. انفصلت بلجيكا بثورة 1830 واعترف باستقلالها لاحقًا.', 'مؤتمرات التسوية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'أي تسوية أوروبية سنة 1648 ارتبطت بالاعتراف باستقلال المقاطعات المتحدة الهولندية والاتحاد السويسري عن الإمبراطورية الرومانية المقدسة؟', '["صلح أوترخت","معاهدة توردسيلاس","صلح وستفاليا","مؤتمر برلين"]'::jsonb, 2, 45, 11, 'multi', 'أنهت معاهدات وستفاليا حرب الثلاثين عامًا سنة 1648، واعترفت رسميًا باستقلال الجمهورية الهولندية والاتحاد السويسري. أما أوترخت فارتبط بحرب الخلافة الإسبانية في القرن الثامن عشر.', 'معاهدات أوروبا');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'ما الوظيفة الجغرافية السياسية الأساسية لـ«ممر واخان» كما تشكل في أواخر القرن التاسع عشر؟', '["منح روسيا منفذًا مباشرًا إلى المحيط الهندي","فصل أراضي الإمبراطورية الروسية عن الهند البريطانية بمنطقة أفغانية عازلة","ربط إيران بالصين عبر سيادة إيرانية","فصل أفغانستان عن الصين كليًا"]'::jsonb, 1, 45, 12, 'multi', 'ثُبت لسان واخان الأفغاني في سياق «اللعبة الكبرى» ليعمل حاجزًا بين مناطق النفوذ الروسية شمالًا والهند البريطانية جنوبًا. وهو يصل أفغانستان بحد قصير مع الصين بدل أن يفصل بينهما.', 'مناطق عازلة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'في خريطة التقسيم الاستعماري لجزيرة غينيا الجديدة قبل الحرب العالمية الأولى، أي قوة كانت تسيطر على النصف الغربي؟', '["هولندا","ألمانيا","بريطانيا","البرتغال"]'::jsonb, 0, 45, 13, 'multi', 'كان الغرب جزءًا من جزر الهند الشرقية الهولندية، بينما تقاسم الشرق نفوذ بريطاني/أسترالي في الجنوب وألماني في الشمال الشرقي. يفسر هذا الإرث بقاء الجزيرة اليوم مقسمة بين إندونيسيا وبابوا غينيا الجديدة.', 'تقسيم استعماري');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'أي مبدأ قانوني استُخدم على نطاق واسع عند استقلال دول أمريكا اللاتينية ثم أفريقيا، ويقضي باحترام الحدود الإدارية السابقة بوصفها حدودًا دولية؟', '["أوتي بوسيديتيس يوريس","حرية البحار","الحدود الطبيعية الحتمية","السيادة المشتركة الدائمة"]'::jsonb, 0, 50, 14, 'multi', 'يقضي مبدأ uti possidetis juris بأن ترث الدول الجديدة الحدود الإدارية التي كانت قائمة عند الاستقلال، بهدف تقليل الفراغ والنزاع الإقليمي. أكدته محكمة العدل الدولية في قضية النزاع الحدودي بين بوركينا فاسو ومالي.', 'قانون الحدود');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'أي نوع من الخطوط يمثل «خط السيطرة» في كشمير وفق اتفاق شملا لعام 1972؟', '["حد دولي نهائي رسمته الأمم المتحدة بين الهند والصين","خط فصل للسيطرة الفعلية بين الهند وباكستان، وليس حدًا دوليًا نهائيًا متفقًا عليه","حد استعماري بين أفغانستان وباكستان","خط ملاحة نهرية بين الهند وبنغلادش"]'::jsonb, 1, 50, 15, 'multi', 'أعاد اتفاق شملا تسمية خط وقف إطلاق النار في كشمير «خط السيطرة» وألزم الطرفين باحترامه دون مساس بالمواقف القانونية لكل منهما. لذا يصف توزيع السيطرة بين الهند وباكستان، ولا يحسم السيادة النهائية.', 'حدود متنازع عليها');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'أي وصف يميز «خط ماكماهون» المرسوم في مؤتمر شملا 1914؟', '["حد نهائي بين الهند وباكستان في البنجاب","خط اقترح للحد بين التبت والهند البريطانية في القطاع الشرقي، وتنازع الصين في شرعيته","خط فصل روسي أفغاني في واخان","حد بحري بين الصين واليابان"]'::jsonb, 1, 50, 16, 'multi', 'ارتبط خط ماكماهون بتفاهمات مؤتمر شملا بين ممثلي بريطانيا والتبت، وهو أساس مطالبة الهند بحدها الشرقي في منطقة أروناتشال براديش. لم تقبل الصين الاتفاق، ولذلك بقيت شرعية الخط موضع نزاع.', 'حدود آسيوية متنازع عليها');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'أي قرار اتخذه مؤتمر منظمة الوحدة الأفريقية بالقاهرة سنة 1964 بشأن الحدود الموروثة؟', '["إعادة رسم كل الحدود وفق التوزيع اللغوي","إلغاء الحدود بين الدول الأعضاء","احترام الحدود القائمة عند نيل الاستقلال","إعادة حدود أفريقيا إلى وضع عام 1884"]'::jsonb, 2, 45, 17, 'multi', 'أعلن قرار القاهرة AHG/Res.16(I) التزام الدول الأعضاء باحترام الحدود القائمة وقت الاستقلال. كان المقصود الحد من موجة نزاعات إعادة الرسم في قارة ورثت حدودًا استعمارية كثيرة.', 'حدود أفريقيا');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'عند تفكك تشيكوسلوفاكيا سلميًا في 1 يناير 1993، ما الدولتان اللتان ورثتا أراضيها؟', '["التشيك وسلوفينيا","سلوفاكيا وكرواتيا","التشيك والمجر","جمهورية التشيك وسلوفاكيا"]'::jsonb, 3, 40, 18, 'multi', 'أنهى «الطلاق المخملي» الاتحاد التشيكوسلوفاكي وأنشأ جمهورية التشيك والجمهورية السلوفاكية. لا علاقة لسلوفينيا، وهي إحدى جمهوريات يوغوسلافيا السابقة، بهذا الانقسام.', 'تفكك الدول');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'أي جمهورية سوفيتية سابقة فصلت جغرافيًا بين الكتلة الرئيسة لأرمينيا وإقليم ناخيتشيفان التابع لأذربيجان بعد 1991؟', '["جورجيا","تركمانستان","أوكرانيا","أرمينيا نفسها تفصل الكتلة الأذربيجانية الرئيسة عن ناخيتشيفان"]'::jsonb, 3, 45, 19, 'multi', 'ناخيتشيفان جمهورية ذاتية الحكم تابعة لأذربيجان لكنها منفصلة عن كتلتها الرئيسة؛ تقع أرمينيا بينهما، بينما يحد ناخيتشيفان أيضًا إيران وتركيا. لذلك الصياغة الأدق أن أراضي أرمينيا تفصل الجزأين الأذربيجانيين.', 'أقاليم منفصلة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'بموجب اتفاقية الأمم المتحدة لقانون البحار، ما خط الأساس المعتاد الذي يقاس منه عرض البحر الإقليمي؟', '["خط أدنى الجَزْر على طول الساحل كما يظهر في الخرائط المعترف بها رسميًا","حافة الجرف القاري الجيولوجية","خط يبعد 200 ميل بحري عن الساحل","الحد الخارجي للمياه الدولية"]'::jsonb, 0, 50, 20, 'multi', 'تنص المادة 5 من الاتفاقية على أن خط الأساس العادي هو خط أدنى الجزر المرسوم على خرائط ساحلية كبيرة المقياس معترف بها رسميًا من الدولة الساحلية. أما 200 ميل بحري فترتبط بالمنطقة الاقتصادية الخالصة، لا بخط الأساس.', 'حدود بحرية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'في ترسيم بحر إقليمي بين دولتين متقابلتين أو متجاورتين وفق المادة 15 من اتفاقية قانون البحار، ما القاعدة الافتراضية عند غياب اتفاق أو حقوق تاريخية أو ظروف خاصة؟', '["امتداد الحدود البرية في خط مستقيم دائمًا","منح البحر كله للدولة ذات الساحل الأطول","خط الوسط المتساوي البعد عن أقرب نقاط خطي الأساس","اتباع أعمق مجرى ملاحي دون استثناء"]'::jsonb, 2, 50, 21, 'multi', 'تمنع المادة 15 مد البحر الإقليمي وراء خط وسط تتساوى نقاطه في البعد عن أقرب نقاط خطوط الأساس، ما لم يوجد اتفاق مختلف أو عنوان تاريخي أو ظروف خاصة تستلزم حلًا آخر.', 'ترسيم بحري');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'أي خط حدودي استعماري رُسم باتفاق 1893 بين الأمير عبد الرحمن خان والسير مورتيمر دوراند؟', '["خط رادكليف بين الهند وباكستان","خط ماكماهون بين الهند والتبت","خط كرزون بين بولندا وروسيا","خط دوراند بين أفغانستان والهند البريطانية، وهو اليوم أساس الحدود الأفغانية الباكستانية"]'::jsonb, 3, 45, 22, 'multi', 'حدد اتفاق 1893 نطاقي النفوذ الأفغاني والبريطاني بخط دوراند. ورثت باكستان الجانب البريطاني عند استقلالها عام 1947، لكن قبول الخط حدًا دوليًا ظل موضع خلاف سياسي أفغاني باكستاني.', 'حدود استعمارية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'في عام 1919، أي ممر منحته أفغانستان للاتحاد السوفيتي فعليًا بفعل الحدود القائمة؟', '["ممر سووالكي","ممر فولدا","ممر كابريفي","لم تمنح ممرًا؛ السؤال يفترض واقعة غير صحيحة، وممر واخان كان قد ثُبت قبل قيام الاتحاد السوفيتي"]'::jsonb, 3, 50, 23, 'multi', 'هذا سؤال تدقيق زمني: الاتحاد السوفيتي لم يُنشأ إلا سنة 1922، وممر واخان تشكل في ترتيبات أواخر القرن التاسع عشر كمنطقة أفغانية عازلة بين الإمبراطوريتين الروسية والبريطانية. لذا لا تصح نسبة «منحه للاتحاد السوفيتي» إلى 1919.', 'تدقيق زمني جغرافي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_37, 'أي معاهدة عام 1923 حددت الإطار الدولي لحدود تركيا الحديثة وحلت محل معاهدة سيفر غير المنفذة؟', '["معاهدة سان ستيفانو","معاهدة لوزان","معاهدة برلين 1878","معاهدة مونترو"]'::jsonb, 1, 45, 24, 'multi', 'اعترفت معاهدة لوزان سنة 1923 بحدود الدولة التركية الجديدة في إطار تسوية ما بعد حرب الاستقلال التركية، وحلت محل تسوية سيفر لعام 1920 التي لم تدخل حيز التطبيق. أما مونترو 1936 فنظمت نظام المضائق التركية.', 'معاهدات الشرق الأوسط');
  END IF;
END $$;



DO $$
DECLARE
  v_lib_id_38 uuid;
BEGIN
  SELECT id INTO v_lib_id_38 FROM quizzes WHERE title = 'أحداث ومصطلحات الشونين الكلاسيكي' LIMIT 1;
  IF v_lib_id_38 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('أحداث ومصطلحات الشونين الكلاسيكي', 'أنمي', '', 'challenge', 'ar', true)
    RETURNING id INTO v_lib_id_38;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_38, 'في دراغون بول، عندما شرح كايو-ساما تقنية «كايو-كين»، ما الذي يميزها عن التحول إلى هيئة ثابتة؟', '["تحول طاقة الخصم إلى طاقة دائمة للمستخدم","تمنح الخلود ما دام المستخدم محافظًا على هالته","تستدعي طاقة الكائنات الحية في كرة واحدة","تضاعف الطاقة والسرعة مؤقتًا مع تعريض الجسد لإجهاد خطير"]'::jsonb, 3, 30, 0, 'multi', 'كايو-كين تضخّم طاقة غوكو وسرعته وقوته لفترة قصيرة، لكن رفع معاملها فوق قدرة الجسد يمزقه بالإجهاد. أما جمع طاقة الكائنات في كرة فهو مبدأ غينكي داما، لا كايو-كين.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_38, 'أي شرط حاسم مكّن غوهان من هزيمة سيل الكامل في صدام الكاميها ميها الأخير؟', '["اندماجه المؤقت مع غوكو","دعم غوكو المعنوي من العالم الآخر وتشتيت فيجيتا لسيل","امتصاصه طاقة أندرويد 18","استخدامه كايو-كين فوق السوبر سايان"]'::jsonb, 1, 30, 1, 'multi', 'كان غوهان مصابًا ويطلق الموجة بيد واحدة؛ شجعه غوكو من العالم الآخر، ووفرت ضربة فيجيتا اللحظة التي كسر فيها غوهان مقاومة سيل. لم يقع اندماج أو امتصاص أو كايو-كين في هذا الحسم.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_38, 'في ون بيس، لماذا كانت قدرة إنيل الكهربائية عاجزة عن إيذاء لوفي مباشرة رغم تفوقها الهائل على معظم خصوم سكايبيا؟', '["لأن لوفي كان يستخدم هاكي التسلح دون وعي","لأن جسد لوفي المطاطي عازل للكهرباء","لأن قبعة القش تمتص الكهرباء","لأن جرس شاندورا أبطل فاكهة إنيل"]'::jsonb, 1, 25, 2, 'multi', 'جسد لوفي المطاطي لا يوصل الكهرباء، ولذلك لم تعمل صواعق إنيل عليه كما عملت على الآخرين. هذه مواجهة خصائص بين فاكهة المطاط وغورو غورو نو مي، وليست نتيجة هاكي أو أداة خارجية.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_38, 'ما الوظيفة الأصلية لـ«البونغليف» ذي اللون الأزرق المعتاد مقارنةً بـ«رود بونغليف» الأحمر في ون بيس؟', '["الأزرق ينقل معلومات تاريخية أو تعليمات، والأحمر يعطي نقطة جغرافية لازمة لتحديد Laugh Tale","الأزرق يحدد إحداثيًا واحدًا للـLaugh Tale، والأحمر يسجل أسلحة فقط","الأزرق لا يقرأه إلا أصحاب حرف D، والأحمر يقرأه الجميع","الأزرق صنعته الحكومة العالمية، والأحمر صنعه القراصنة"]'::jsonb, 0, 35, 3, 'multi', 'البونغليفات العادية تحمل نصوصًا تاريخية أو معلومات، ومنها ما يرشد إلى موضع نوع آخر؛ أما أحجار الطريق الحمراء الأربعة فتعطي نقاطًا يُستخرج من تقاطعها موقع Laugh Tale.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_38, 'في نظام التشاكرا بناروتو، ماذا يحدث عند مزج التحول في طبيعة الرياح بالتحول في طبيعة الماء وفق المثال الأشهر في السلسلة؟', '["ينتج عنصر الخشب","ينتج عنصر الجليد","ينتج عنصر الغليان","ينتج عنصر المغناطيس"]'::jsonb, 1, 25, 4, 'multi', 'إطلاق الجليد (Hyōton) كِكّاي غِنكاي يمزج طبيعتي الماء والرياح، كما يظهر مع هاكو. الخشب يمزج الماء والأرض، بينما الغليان يمزج الماء والنار.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_38, 'لماذا عُدّ ختم «الشينيغامي» الذي استخدمه الهوكاغي الثالث ضد أوروتشيمارو تضحية لا نينجتسو عادية؟', '["لأنه يمحو ذاكرة المستخدم نهائيًا","لأنه ينقل عمر المستخدم إلى الخصم","لأن الشينيغامي يلتهم روح المستخدم بعد انتزاع روح الهدف","لأنه يمنع المستخدم من استعمال التشاكرا شهرًا"]'::jsonb, 2, 30, 5, 'multi', 'شيكي فوجين يستدعي إله الموت لانتزاع الروح وختمها، ثم تكون روح المستعمل نفسه ثمن التقنية. لذلك مات هيروزن بعد أن ختم ذراعي أوروتشيمارو، كما مات ميناتو بعد استعمالها سابقًا.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_38, 'أي فرق جوهري يفصل «الشikai» عن «البانكاي» في بليتش؟', '["الشikai إطلاق أول لاسم وقوة الزانباكتو، والبانكاي إطلاقها النهائي المكتمل","الشikai خاص بالكيدو، والبانكاي خاص بالهولو","الشikai لا يحتاج زانباكتو، والبانكاي يحتاج سيفين","الشikai لا يستعمله إلا القادة، والبانكاي متاح لكل الشينيغامي"]'::jsonb, 0, 25, 6, 'multi', 'الشikai هو مرحلة الإطلاق الأول للزانباكتو بعد معرفة اسمه، بينما البانكاي هو الإطلاق النهائي الذي يتطلب تجسيد روح السيف وإخضاعها عادةً. امتلاك البانكاي نادر ومقياس تقليدي لقدرة القادة.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_38, 'ما الذي كشفه أوراهارا عن «الهوجيوكو» بما يصحح الفكرة القائلة إنه مجرد أداة تفصل حدود الشينيغامي والهولو؟', '["أنه يخزن أرواحًا بشرية ثم يعيدها للحياة","أنه يحقق رغبات المحيطين به إذا امتلكوا القدرة الكامنة لتحقيقها","أنه يلغي أسماء الزانباكتو","أنه نسخة صناعية من ملك الأرواح بلا إرادة"]'::jsonb, 1, 35, 7, 'multi', 'يشرح أوراهارا أن القوة الحقيقية للهوجيوكو هي التقاط قلوب من حوله وتجسيد رغباتهم حين تكون لديهم قابلية تحقيقها؛ تجاوز حدود الشينيغامي والهولو كان تطبيقًا لهذه الخاصية، لا تعريفها الكامل.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_38, 'في هنتر × هنتر، أي مبدأ من مبادئ النين الأربعة يخفي الهالة ويجعل المستخدم أكثر عرضة لضربات النين؟', '["زيتسو Zetsu","تين Ten","رين Ren","هاتسو Hatsu"]'::jsonb, 0, 20, 8, 'multi', 'زيتسو يغلق عقد الهالة ويوقف تدفقها، فيفيد في إخفاء الحضور واستعادة النشاط، لكنه يترك الجسد بلا غلاف هالة واقٍ أمام هجوم نين. تين يحافظ على الغلاف، ورين يضخم الخرج.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_38, 'كيف زاد كورابيكا فاعلية «Chain Jail» إلى حد إخضاع أعضاء العنكبوت الأقوياء؟', '["ضحّى بحاسة البصر كلما استخدم السلسلة","اشترط أن يكون القمر مكتملًا","ربطها بقسم لاستخدامها على العنكبوت فقط، على أن يموت إن استعملها على غيرهم","نقل ملكية السلسلة إلى الإمبراطور تايم"]'::jsonb, 2, 30, 9, 'multi', 'فرض كورابيكا قيدًا وقسمًا شديدين: Chain Jail مخصصة لأعضاء فرقة العنكبوت، واستخدامها على سواهم يفعّل Judgement Chain المغروسة في قلبه ويقتله. شدة المخاطرة رفعت قوة السلسلة.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_38, 'في يو يو هاكوشو، ما الصفة التي جعلت «ريغان» يوسكي ملائمًا لمواجهة الأرواح والشياطين؟', '["إنه سيف مصنوع من طاقة شيطانية مسروقة","إنه طاقة روحية مركزة يطلقها من إصبعه","إنه تعويذة توقف الزمن","إنه حاجز يعكس أي هجوم جسدي"]'::jsonb, 1, 20, 10, 'multi', 'الريغان، أو المسدس الروحي، يركز ريكي يوسكي في طلقة من السبابة. نمو مخزونه الروحي وتدريبه يرفعان عدد الطلقات وقوتها؛ ليست التقنية سيفًا أو حاجزًا.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_38, 'ما الغرض الحقيقي من بطولة الظلام في خطة توغورو الأصغر، بعيدًا عن الجائزة الرسمية للبطولة؟', '["الحصول على كتاب أسرار عالم الأرواح","فتح بوابة دائمة إلى عالم البشر","استعادة جسده البشري والتخلي عن الشيطنة","إجبار يوسكي على بلوغ قوة تكفي لمنحه قتالًا حتى الموت"]'::jsonb, 3, 30, 11, 'multi', 'دفع توغورو يوسكي وفريقه إلى البطولة ورفع الضغط عليهم كي ينضج يوسكي إلى خصم يستطيع قتاله بكامل قوته. كان يبحث عن اختبار نهائي وعقاب ذاتي مرتبط بماضيه، لا عن ثروة البطولة.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_38, 'في سانت سيا، ما العلاقة بين «الكوزمو» والحاسة السابعة التي يحتاجها البرونزيون لمجاراة فرسان الذهب؟', '["الحاسة السابعة تلغي الكوزمو وتستبدله بالسحر","الكوزمو درع مادي والحاسة السابعة سلاح مستقل","الحاسة السابعة لا تُستخدم إلا في العالم السفلي","إيقاظ الحاسة السابعة يعني تفجير الكوزمو إلى مستوى يتجاوز الحواس الست"]'::jsonb, 3, 25, 12, 'multi', 'الكوزمو هو الكون الداخلي الذي يحرقه القديس ليولد القوة؛ وإدراك الحاسة السابعة يرفع هذا الاحتراق إلى المجال الذي يتحرك ويقاتل فيه فرسان الذهب، بما في ذلك سرعة الضوء.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_38, 'لماذا لم يكن الوصول إلى «الحاسة الثامنة» في فصل هاديس مجرد زيادة هجومية جديدة؟', '["لأنها تحول الدرع البرونزي إلى ذهبي دائمًا","لأنها تعيد جميع الموتى إلى الحياة","لأنها تسمح بالذهاب إلى العالم السفلي أحياءً مع الاحتفاظ بالإرادة والقدرة","لأنها تمنع آلهة الأولمب من استعمال الكوزمو"]'::jsonb, 2, 35, 13, 'multi', 'الحاسة الثامنة، أراياشيكي، تتيح للقديس أن يدخل عالم الموتى دون أن يخضع لقوانينه كروح ميتة فاقدة للحرية. لذا كانت مفتاح غزو عالم هاديس أحياءً، لا مضاعف ضرر بسيطًا.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_38, 'في روروني كنشن، لماذا يستخدم كنشن سيف «ساكاباتو» ذا النصل المعكوس؟', '["لأنه لا يستطيع سحب سيف تقليدي من غمده","لأن النصل المعكوس وحده يقطع الدروع","لأنه سلاح رسمي تمنحه حكومة ميجي للشرطة","ليفي بنذره ألّا يقتل بعد عصر الباكوماتسو مع بقائه قادرًا على القتال"]'::jsonb, 3, 20, 14, 'multi', 'يحمل كنشن الساكاباتو كي يقاتل بحافة غير قاتلة بعد أن أقسم ألّا يعود إلى القتل الذي مارسه بصفته هيتوكيري باتوساي. السيف رمز عملي لتكفيره، لا سلاحًا حكوميًا.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_38, 'ما المبدأ الذي يجعل «أماكاكيرو ريو نو هيراميكي» أخطر من بقية تقنيات هيتن ميتسوروغي في تدريب كنشن؟', '["لا تعمل إلا إذا كان السيف مكسورًا","تمتص قوة ضربة الخصم بلا حركة","تتطلب خطوة أولى بالقدم اليسرى تتحدى غريزة المبارز وتحافظ على استمرار الدوران","تستلزم قتل المعلم لانتقال التقنية سحريًا"]'::jsonb, 2, 35, 15, 'multi', 'سر التقنية ضربة باتّوجوتسو فائقة تتقدم فيها القدم اليسرى؛ الخطوة غير المألوفة تمنع توقف الجسد وتزيد التسارع، لكن الخطأ يعرّض الساق والنفس لخطر قاتل. اجتيازها ارتبط أيضًا بإرادة كنشن في الحياة.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_38, 'في ناروتو، لماذا لم يكن «إيزاناغي» عند دانزو وسيلة مجانية لإلغاء الموت أو الإصابة؟', '["لأنه يحتاج موافقة الكيوبي في كل مرة","لأنه يعيد الزمن للعالم كله ويحذف ذاكرة المستخدم","لأنه يعمل مرة واحدة لكل عشيرة لا لكل شخص","لأن كل تفعيل يستهلك شارينغان ويغلق عينًا مستخدمة بعد مدة محدودة"]'::jsonb, 3, 30, 16, 'multi', 'إيزاناغي يحول الضرر والموت الواقعين على المستخدم إلى وهم خلال نافذة قصيرة، لكنه يفقد نور الشارينغان التي تديره. لذلك زرع دانزو عدة عيون في ذراعه لتمديد مرات الاستخدام.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_38, 'في ون بيس، ما الفارق الوظيفي بين «مانترا» سكايبيا و«هاكي التنبؤ» كما اتضح لاحقًا؟', '["لا فرق جوهريًا؛ مانترا هو الاسم المحلي في سكايبيا لهاكي التنبؤ","مانترا قدرة من فاكهة شيطان، والهاكي تقنية سيف","مانترا تسمع الموتى فقط، والهاكي يقرأ النصوص","مانترا أقوى دائمًا لأنها لا تعتمد على الهدوء"]'::jsonb, 0, 30, 17, 'multi', 'المصطلحان يشيران إلى القدرة نفسها: استشعار حضور الآخرين ونواياهم وحركاتهم. سماها أهل جزر السماء «مانترا»، ثم عرّف رايلي التصنيف العام باسم كينبونشوكو هاكي.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_38, 'في بليتش، ما الذي يجعل «غارغانتا» مختلفًا عن «سينكايمون» في التنقل بين العوالم؟', '["غارغانتا بوابة للبشر فقط، وسينكايمون للهولو فقط","كلاهما اسم للبوابة نفسها بحسب الترجمة","غارغانتا ممر فضائي يستخدمه الهولو والأرانكار عبر الفراغ، وسينكايمون بوابة الشينيغامي بين عالم الأرواح وعالم البشر","سينكايمون لا ينقل الأجساد بينما غارغانتا لا ينقل الأرواح"]'::jsonb, 2, 30, 18, 'multi', 'يفتح الهولو والأرانكار الغارغانتا في الفراغ الواقع بين العوالم، بينما يستعمل الشينيغامي السينكايمون للعبور المنظم، مارّين بالدانغاي عند الربط بين مجتمع الأرواح وعالم البشر.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_38, 'في هنتر × هنتر، لماذا كان تحويل غون ضد نيفربيتو أقرب إلى «عقد نين» منه إلى تحول تدريبي طبيعي؟', '["لأنه قدّم كل موهبته ومستقبله المحتمل ثمنًا لقوة كان سيبلغها بعد سنوات","لأنه استعار هالة كيلوا ثم أعادها","لأنه أكل قلب ملك النمل","لأنه فعّل تخصص الإمبراطور تايم"]'::jsonb, 0, 35, 19, 'multi', 'في غضبه قيّد غون نفسه بحيث يحصل فورًا على كل القوة التي قد يبلغها مستقبلًا، مقابل التضحية بموهبته وقدرته وحالته الجسدية. لذلك كان الأثر اللاحق مدمرًا ولم يكن مرحلة تدريب قابلة للتكرار.', '');
  END IF;
END $$;



DO $$
DECLARE
  v_lib_id_39 uuid;
BEGIN
  SELECT id INTO v_lib_id_39 FROM quizzes WHERE title = 'تفاصيل المانجا، الاستوديوهات والمخرجين' LIMIT 1;
  IF v_lib_id_39 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('تفاصيل المانجا، الاستوديوهات والمخرجين', 'أنمي', '', 'challenge', 'ar', true)
    RETURNING id INTO v_lib_id_39;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_39, 'أي توصيف يطابق انتقال إنتاج أنمي «هجوم العمالقة» التلفزيوني بين الاستوديوهات؟', '["أنتج MAPPA المواسم الثلاثة الأولى، ثم تولى WIT Studio الموسم الختامي","أنتج Production I.G السلسلة كلها من دون انتقال","أنتج Bones الموسمين الأولين ثم أكمل MAPPA","أنتج WIT Studio المواسم الثلاثة الأولى، ثم تولى MAPPA موسم The Final Season"]'::jsonb, 3, 25, 0, 'multi', 'تسجل الصفحات الرسمية WIT Studio جهةً للرسوم المتحركة في المواسم الثلاثة الأولى، بينما تسجل MAPPA في The Final Season. لذلك فالانتقال الصحيح حدث عند بدء الموسم الختامي، لا في منتصف المواسم السابقة.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_39, 'من المخرج الذي ارتبط بإخراج «كاوبوي بيبوب» التلفزيوني في استوديو Sunrise؟', '["ساتوشي كون","مامورو أوشي","شينيتشيرو واتانابي","يوسا ماساكي"]'::jsonb, 2, 20, 1, 'multi', 'اعتمادات المسلسل تسمي شينيتشيرو واتانابي مخرجًا، وكان العمل من إنتاج Sunrise. أما ساتوشي كون ومامورو أوشي ويوسا ماساكي فمخرجون بارزون، لكنهم لم يخرجوا هذا المسلسل.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_39, 'ما الاقتران الصحيح بين أنمي «ديث نوت» التلفزيوني واستوديوه ومخرجه؟', '["Bones — سيجي ميزوشيما","Production I.G — كينجي كامياما","J.C.STAFF — تشيكارا ساكوراي","Madhouse — تيتسورو أراكي"]'::jsonb, 3, 20, 2, 'multi', 'اعتمادات نسخة 2006 التلفزيونية من Death Note تنسب إنتاج الرسوم إلى Madhouse والإخراج إلى تيتسورو أراكي. الخيارات الأخرى تجمع أسماء حقيقية لكنها تخص أعمالًا وإنتاجات مختلفة.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_39, 'أي استوديو أنتج الموسم الأول من «ون بنش مان»، قبل انتقال الموسم الثاني إلى J.C.STAFF؟', '["Bones","Madhouse","A-1 Pictures","Studio Pierrot"]'::jsonb, 1, 20, 3, 'multi', 'الموسم الأول أُنجز في Madhouse بإخراج شينغو ناتسومي، ثم تغيرت جهة إنتاج الرسوم في الموسم الثاني إلى J.C.STAFF. لذا لا ينبغي نسبة الموسمين إلى استوديو واحد.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_39, 'ما الاستوديو الذي أنتج اقتباسي «Fullmetal Alchemist» لعام 2003 و«Brotherhood» لعام 2009 رغم اختلاف المخرج؟', '["Madhouse","Bones","Gainax","Kyoto Animation"]'::jsonb, 1, 20, 4, 'multi', 'كلا الاقتباسين من إنتاج Bones؛ أخرج نسخة 2003 سيجي ميزوشيما، بينما أخرج Brotherhood ياسوهيرو إيري. ثبات الاستوديو لا يعني ثبات القيادة الإخراجية أو مسار الاقتباس.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_39, 'أي اقتران يطابق إنتاج «قاتل الشياطين: كيميتسو نو يايبا» التلفزيوني؟', '["ufotable — هاروؤو سوتوزاكي","MAPPA — سونغهو بارك","Bones — يوزورو تاتشيكاوا","WIT Studio — تتسورو أراكي"]'::jsonb, 0, 20, 5, 'multi', 'الموقع الرسمي يسجل ufotable لإنتاج الرسوم المتحركة وهاروؤو سوتوزاكي للإخراج. بقية الأزواج مرتبطة بأعمال أنمي معروفة، ولذلك تبدو معقولة لكنها لا تخص Kimetsu no Yaiba.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_39, 'في أي مجلة بدأت ناوكو تاكيوتشي نشر مانجا «Sailor Moon»؟', '["Weekly Shonen Jump","Big Comic Original","Nakayoshi","Monthly Afternoon"]'::jsonb, 2, 20, 6, 'multi', 'نشرت Kodansha مانجا Sailor Moon في مجلة Nakayoshi الموجهة أساسًا لفئة الشوجو. المجلات الأخرى حقيقية، لكنها تنتمي إلى خطوط تحريرية وناشرين أو جماهير مختلفة.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_39, 'أي مخرج تولى أنمي «Frieren: Beyond Journey’s End» في استوديو Madhouse؟', '["شينغو ناتسومي","كييتشيرو سايتو","هيروشي كوجينا","ماساؤكي كوجيما"]'::jsonb, 1, 20, 7, 'multi', 'تنسب الصفحة الرسمية إخراج Frieren إلى كييتشيرو سايتو وإنتاج الرسوم إلى Madhouse. أما الأسماء الأخرى فكلها لمخرجين عملوا مع Madhouse أو في محيط إنتاجات مشابهة، ما يجعلها مشتتات مهنية لا عشوائية.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_39, 'أي عبارة تضبط تغير القيادة الإخراجية مع انتقال «هجوم العمالقة» إلى MAPPA؟', '["استمر تتسورو أراكي مخرجًا منفردًا لكل أجزاء The Final Season","انتقل ماساشي كويزوكا إلى MAPPA وأخرج الموسم الختامي كاملًا","أخرج يويتشيرو هاياشي المواسم الثلاثة الأولى ثم سلمه لتتسورو أراكي","حل يويتشيرو هاياشي مخرجًا لـThe Final Season بعد تتسورو أراكي وماسا شي كويزوكا في حقبة WIT"]'::jsonb, 3, 35, 8, 'multi', 'مع انتقال الإنتاج من WIT إلى MAPPA تغيرت القيادة إلى يويتشيرو هاياشي في The Final Season. ارتبط تتسورو أراكي بالإخراج أولًا ثم بدور المخرج العام، وتولى ماساشي كويزوكا إخراج الموسمين الثاني والثالث في حقبة WIT.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_39, 'أي مقارنة صحيحة بين اقتباسي «Hunter × Hunter» التلفزيونيين لعامي 1999 و2011؟', '["النسختان من Madhouse وبالمخرج نفسه","نسخة 1999 من Bones ونسخة 2011 من MAPPA","نسخة 1999 من Pierrot بإخراج نورييوكي آبي ونسخة 2011 من Toei","نسخة 1999 من Nippon Animation بإخراج كازوهيرو فوروهاشي، ونسخة 2011 من Madhouse بإخراج هيروشي كوجينا"]'::jsonb, 3, 35, 9, 'multi', 'اقتباس 1999 حمل إنتاج Nippon Animation وإخراج كازوهيرو فوروهاشي، بينما أعيد تقديم العمل تلفزيونيًا سنة 2011 في Madhouse بإخراج هيروشي كوجينا. الاختلاف إعادة إنتاج كاملة لا مجرد موسم لاحق.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_39, 'عند مقارنة «Ghost in the Shell» السينمائي (1995) بمسلسل «Stand Alone Complex»، ما الاقتران الصحيح للمخرجين؟', '["كينجي كامياما للفيلم، ومامورو أوشي للمسلسل","مامورو أوشي للفيلم، وكينجي كامياما للمسلسل","ساتوشي كون للفيلم، وشينيتشيرو واتانابي للمسلسل","هيرويوكي أوكورا للفيلم، وكاتسوهيرو أوتومو للمسلسل"]'::jsonb, 1, 30, 10, 'multi', 'أخرج مامورو أوشي فيلم 1995، بينما أخرج كينجي كامياما Stand Alone Complex. كلاهما من إنتاج Production I.G، لكن وحدة الاستوديو لا تعني أن العملين يشتركان في المخرج أو الاستمرارية السردية.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_39, 'ما التفصيل الإنتاجي الذي بقي ثابتًا عند انتقال «Vinland Saga» من موسمه الأول إلى الثاني؟', '["استمر شوهي يابوتا مخرجًا رغم انتقال إنتاج الرسوم من WIT Studio إلى MAPPA","استمر WIT Studio لكن تغير المخرج إلى سونغهو بارك","انتقل العمل إلى Bones وبقي المؤلف الموسيقي وحده","تولى ماكوتو يوكيمورا الإخراج بدل كتابة المانجا"]'::jsonb, 0, 30, 11, 'multi', 'الموسم الأول من إنتاج WIT Studio والثاني من MAPPA، لكن شوهي يابوتا واصل مهمة الإخراج. يوضح ذلك أن انتقال الاستوديو لا يستلزم تبدل كل الطاقم القيادي.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_39, 'ما العلاقة الزمنية الصحيحة بين مانجا «Neon Genesis Evangelion» لساداموتو وبث الأنمي التلفزيوني؟', '["بدأت المانجا بعد نهاية الفيلم The End of Evangelion بوصفها تكملة رسمية","اكتملت المانجا كلها قبل بدء إنتاج الأنمي","بدأ نشر المانجا قبل العرض التلفزيوني، مع أنها صُممت ضمن المشروع الإعلامي المرتبط بالأنمي وليست الأصل المكتمل الذي اقتُبس حرفيًا","كانت المانجا اقتباسًا مباشرًا لرواية مكتملة لهايدياكي أنو"]'::jsonb, 2, 35, 12, 'multi', 'بدأ تسلسل مانجا يوشيوكي ساداموتو في Monthly Shōnen Ace أواخر 1994، قبل بث الأنمي في أكتوبر 1995، لكنها كانت جزءًا من إطلاق المشروع وليست مانجا مكتملة سبقت الأنمي بوصفها مادته الأصلية التقليدية.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_39, 'أي توصيف دقيق لتغير الإخراج بين الموسمين الأول والثاني من «Jujutsu Kaisen»؟', '["أخرج شوتا غوشوزونو الموسمين ثم انتقل العمل من MAPPA إلى Bones","أخرج سونغهو بارك الموسم الأول، وأخرج شوتا غوشوزونو الموسم الثاني، مع بقاء MAPPA استوديو الرسوم","أخرج سونغهو بارك الموسم الثاني فقط بعد انتقاله من Madhouse","لم يتغير المخرج ولا الاستوديو بين الموسمين"]'::jsonb, 1, 30, 13, 'multi', 'تسجل اعتمادات الموسم الأول سونغهو بارك مخرجًا، بينما تسجل اعتمادات الموسم الثاني شوتا غوشوزونو. ظل MAPPA مسؤولًا عن إنتاج الرسوم في الموسمين، فالتغير هنا في القيادة الإخراجية لا في الاستوديو.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_39, 'في الموسم الثالث من «Mob Psycho 100»، كيف وُزعت القيادة الإخراجية مقارنة بالموسمين السابقين؟', '["أصبح تاكاهيرو هاسوي المخرج، مع بقاء يوزورو تاتشيكاوا مخرجًا عامًا","غادر يوزورو تاتشيكاوا كل دور وتولى شينغو ناتسومي الإخراج العام","انتقل العمل إلى MAPPA وأخرجه يويتشيرو هاياشي","تولى مؤلف المانجا ONE الإخراج والحبكة المصورة"]'::jsonb, 0, 35, 14, 'multi', 'في Mob Psycho 100 III سُجل تاكاهيرو هاسوي مخرجًا، بينما انتقل يوزورو تاتشيكاوا، مخرج الموسمين السابقين، إلى منصب المخرج العام. واستمر Bones في إنتاج الرسوم.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_39, 'لماذا يُعد اسم «مامورو هاتاكياما» في اعتمادات إخراج «Kaguya-sama: Love Is War» حالة لافتة؟', '["لأنه اسم جماعي لجميع مخرجي A-1 Pictures","لأنه الاسم الياباني الرسمي لمؤلف المانجا أكا أكاساكا","لأنه اسم مهني استخدمه المخرج شينيتشي أوماتا","لأنه اسم الاستوديو الفرعي الذي نفذ الموسم الأول"]'::jsonb, 2, 35, 15, 'multi', 'مامورو هاتاكياما هو الاسم المهني الذي تُنسب به أعمال إلى المخرج شينيتشي أوماتا، ومن بينها Kaguya-sama. لذلك لا يشير الاعتماد إلى استوديو أو مؤلف المانجا أو لجنة إخراج جماعية.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_39, 'أي اقتران يصف أنمي «Berserk» التلفزيوني لعام 1997، لا ثلاثية الأفلام ولا نسخة 2016؟', '["OLM — ناوهيتو تاكاهاشي","Studio 4°C — توشييوكي كوبوكا","GEMBA — شين إيتاغاكي","Madhouse — ماساؤكي كوجيما"]'::jsonb, 0, 30, 16, 'multi', 'نسخة التلفزيون لعام 1997 أخرجها ناوهيتو تاكاهاشي وأنتجت رسومها OLM. Studio 4°C ارتبط بثلاثية Golden Age، بينما ارتبطت GEMBA وطاقم مختلف بنسخة 2016.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_39, 'ما الاقتران الصحيح لاقتباس «Monster» التلفزيوني عن مانجا ناوكي أوراساوا؟', '["Madhouse — ماساؤكي كوجيما","Production I.G — كينجي كامياما","Bones — ياسوهيرو إيري","Nippon Animation — كازوهيرو فوروهاشي"]'::jsonb, 0, 30, 17, 'multi', 'أنتج Madhouse رسوم مسلسل Monster وأخرجه ماساؤكي كوجيما. المشتتات تجمع استوديوهات ومخرجين متوافقين مهنيًا فعلًا، لكن اقترانهم يعود إلى أعمال أخرى.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_39, 'أي وصف يميز اقتباس «PLUTO» الصادر في 2023 من ناحية الاستوديو والمخرج؟', '["أنتجه Madhouse وأخرجه ماساؤكي كوجيما","أنتجه MAPPA وأخرجه ريو ناكاياما","أنتجه Production I.G وأخرجه مامورو أوشي","أنتجه Studio M2 وأخرجه توشيو كاواغوتشي"]'::jsonb, 3, 30, 18, 'multi', 'تسجل الاعتمادات الرسمية Studio M2 لإنتاج الرسوم وتوشيو كاواغوتشي للإخراج. قد يلتبس الأمر بسبب صلة مؤسس M2 ماساؤو ماروي بتاريخ Madhouse وMAPPA، لكن الاستوديو المعتمد للعمل هو M2.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_39, 'أي مقارنة صحيحة بين إخراج «One-Punch Man» في موسميه الأول والثاني؟', '["أخرج تشيكارا ساكوراي الأول، ثم شينغو ناتسومي الثاني في الاستوديو نفسه","أخرج يوزورو تاتشيكاوا الموسمين في Bones","أخرج شينغو ناتسومي الأول في Madhouse، وأخرج تشيكارا ساكوراي الثاني في J.C.STAFF","أخرج سونغهو بارك الأول، ثم شوتا غوشوزونو الثاني في MAPPA"]'::jsonb, 2, 30, 19, 'multi', 'تغير في الموسم الثاني كل من استوديو الرسوم والمخرج: من Madhouse وشينغو ناتسومي إلى J.C.STAFF وتشيكارا ساكوراي. وهذا أدق من القول إن التغيير اقتصر على الاستوديو فقط.', '');
  END IF;
END $$;



DO $$
DECLARE
  v_lib_id_40 uuid;
BEGIN
  SELECT id INTO v_lib_id_40 FROM quizzes WHERE title = 'اكتشافات واختراعات غيّرت العالم' LIMIT 1;
  IF v_lib_id_40 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('اكتشافات واختراعات غيّرت العالم', 'معلومات عامة', '', 'medium_high', 'ar', true)
    RETURNING id INTO v_lib_id_40;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'ما التحسين التقني الذي ميّز مطبعة يوهانس غوتنبرغ في أوروبا القرن الخامس عشر وجعل إنتاج الكتب واسع النطاق أكثر عملية من نسخها يدويًا؟', '["اختراع الورق المصنوع من ألياف الكتان لأول مرة","استبدال الأبجدية اللاتينية بنظام تصويري","جمع الحروف المعدنية المتحركة مع مكبس وحبر زيتي مناسب للطباعة","ابتكار الطباعة الحجرية على ألواح من الحجر الجيري"]'::jsonb, 2, 30, 0, 'multi', 'لم يخترع غوتنبرغ الورق ولا مبدأ الطباعة المتحركة عالميًا؛ فقد سبقت تقنيات آسيوية عمله. تمثّل إسهامه الأوروبي الحاسم في منظومة متكاملة تضم حروفًا معدنية قابلة لإعادة الاستخدام، وقوالب دقيقة، وحبرًا زيتيًا، ومكبسًا، فصار نسخ النصوص بكميات كبيرة أكثر كفاءة واتساقًا.', 'الطباعة ونقل المعرفة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'أي تعديل أدخله جيمس واط على المحرك البخاري النيوكومنـي خفّض هدر الطاقة الناتج من تسخين الأسطوانة وتبريدها بالتناوب؟', '["مكثّف منفصل عن الأسطوانة","مرجل أنبوبي يعمل بضغط فائق","عنفة بخارية متعددة المراحل","إشعال داخلي بشرارة كهربائية"]'::jsonb, 0, 30, 1, 'multi', 'فصل واط عملية التكثيف عن الأسطوانة العاملة، فبقيت الأسطوانة ساخنة بينما تكثف البخار في وعاء مستقل. خفّض ذلك فقد الحرارة ورفع الكفاءة مقارنة بمحرك نيوكومن؛ لذا الأدق وصف واط بأنه محسّن ثوري للمحرك البخاري لا مخترعه الوحيد.', 'الطاقة والثورة الصناعية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'في تجربة إدوارد جينر سنة 1796 التي مهّدت لأول لقاح ناجح، استُخدمت مادة مأخوذة من إصابة بأي مرض للحماية من الجدري؟', '["الحصبة","الجمرة الخبيثة","الطاعون الدبلي","جدري البقر"]'::jsonb, 3, 25, 2, 'multi', 'استخدم جينر مادة من بثرة جدري البقر لدى سارة نلمز لتلقيح جيمس فيبس، ثم أظهر حمايته من الجدري. وكانت ممارسات التجدير أقدم في آسيا وأفريقيا؛ أما تجربة جينر فأسست للتلقيح بمصدر أقل خطورة ولانتشار مفهوم اللقاح الحديث.', 'اللقاحات والصحة العامة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'ما الملاحظة التي قادت ألكسندر فليمنغ عام 1928 إلى التعرف على التأثير المضاد للبكتيريا للبنسلين؟', '["موت البكتيريا بعد تعرضها للأشعة السينية","توقف نمو البكتيريا في مزرعة خالية من الأكسجين","تحول الفيروسات إلى بلورات في وسط ملحي","وجود منطقة خالية من نمو المكورات العنقودية حول عفن من جنس Penicillium"]'::jsonb, 3, 30, 3, 'multi', 'لاحظ فليمنغ أن تلوث طبق مزروع بالمكورات العنقودية بعفن Penicillium ترافق مع تثبيط البكتيريا حوله. أما تحويل الملاحظة إلى دواء قابل للعلاج على نطاق واسع فاعتمد لاحقًا على عمل هوارد فلوري وإرنست تشين وفريقهما والإنتاج الصناعي.', 'المضادات الحيوية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'أي اكتشاف تجريبي ارتبط باسم مايكل فاراداي سنة 1831 وأصبح أساس عمل المولدات والمحولات الكهربائية؟', '["الحث الكهرومغناطيسي","التأثير الكهروضوئي","الموصلية الفائقة","الانشطار النووي"]'::jsonb, 0, 25, 4, 'multi', 'أظهر فاراداي أن تغير الفيض المغناطيسي عبر دائرة يولّد قوة دافعة كهربائية فيها. هذا مبدأ الحث الكهرومغناطيسي الذي تقوم عليه المولدات بتحويل الحركة إلى كهرباء والمحولات بنقل الطاقة بين ملفات مقترنة مغناطيسيًا.', 'الكهرباء والمغناطيسية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'ما العنصر الذي تنبأ ديميتري مندليف بخصائصه باسم «إيكا-ألومنيوم»، ثم عُزل لاحقًا وأكد نجاح منهجه الدوري؟', '["الجرمانيوم","السكانديوم","الغاليوم","الرينيوم"]'::jsonb, 2, 25, 5, 'multi', 'ترك مندليف فجوات في جدوله وتنبأ بخصائص عناصر مجهولة. كان «إيكا-ألومنيوم» هو الغاليوم الذي اكتشفه بول-إميل لوكوك دي بواسبودران سنة 1875، وجاءت خصائصه قريبة من تنبؤات مندليف، ما عزز قوة القانون الدوري.', 'الكيمياء والجدول الدوري');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'ما الأداة التي ابتكرها إيفانجليستا توريتشيلي باستخدام عمود من الزئبق، وأثبتت عمليًا إمكان قياس ضغط الهواء؟', '["البارومتر","المانومتر التفاضلي","المسعر","مقياس الرطوبة ذي البصلة الرطبة"]'::jsonb, 0, 25, 6, 'multi', 'قلب توريتشيلي أنبوبًا مملوءًا بالزئبق في حوض زئبق، فاستقر العمود عند ارتفاع تحدده موازنة ضغط الجو. كان الفراغ أعلى العمود مهمًا أيضًا في تقويض الاعتقاد بأن الطبيعة لا تسمح بوجود فراغ.', 'أدوات القياس');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'لماذا كان الكرونومتر البحري الذي طوّره جون هاريسون بالغ الأهمية للملاحة في القرن الثامن عشر؟', '["قاس عمق البحر من زمن رجوع الصدى","أمّن وقتًا مرجعيًا دقيقًا في البحر، فمكّن من حساب خط الطول","حدد خط العرض من المجال المغناطيسي وحده","تنبأ بالعواصف من تغير رطوبة الهواء"]'::jsonb, 1, 30, 7, 'multi', 'يُستخرج فرق خط الطول من فرق الزمن بين الوقت المحلي ووقت مرجعي معلوم؛ كل ساعة تقابل 15 درجة. نجحت ساعات هاريسون في حفظ الوقت بدقة رغم حركة السفينة وتغير الحرارة، فحلت جانبًا عمليًا حاسمًا من «مسألة خط الطول».', 'الملاحة وقياس الزمن');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'أي وصف أدق لأول ترانزستور ناجح عُرض في مختبرات بِل سنة 1947؟', '["ترانزستور تأثير مجال من السيليكون صنعه كيلبي","صمام مفرغ ثلاثي صغّره إديسون","ترانزستور تلامس نقطي من الجرمانيوم صنعه باردين وبراتين ضمن فريق قاده شوكلي","دائرة متكاملة من الجرمانيوم صنعها نويس"]'::jsonb, 2, 30, 8, 'multi', 'حقق جون باردين ووالتر براتين أول تضخيم ناجح بترانزستور التلامس النقطي الجرمانيومي في فريق وليام شوكلي. ثم طور شوكلي مفهوم ترانزستور الوصلة؛ وتقاسم الثلاثة نوبل الفيزياء لعام 1956، لذلك لا يصح اختزال الإنجاز في اسم واحد.', 'الإلكترونيات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'أي قرار اتخذه CERN في 30 أبريل 1993 أسهم مباشرة في الانتشار العالمي للشبكة العنكبوتية؟', '["تحويل بروتوكول الإنترنت إلى شبكة عسكرية مغلقة","إتاحة برمجيات الويب في الملكية العامة ثم بترخيص مفتوح","فرض رسوم على كل رابط تشعبي","استبدال HTML بنظام ملفات خاص بأجهزة NeXT"]'::jsonb, 1, 25, 9, 'multi', 'ابتكر تيم برنرز-لي الويب في CERN لتبادل المعلومات بين العلماء، وشملت المنظومة خادمًا ومتصفحًا/محررًا وعناوين URL وHTTP وHTML. سمح إعلان CERN البرمجيات في الملكية العامة ثم إصدارها بترخيص مفتوح بتبنيها بلا رسوم ترخيص، فساعد الويب على الازدهار.', 'الويب والاتصالات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'في عملية هابر-بوش، ما الزوج الذي يتفاعل صناعيًا تحت ضغط وحرارة وبوجود حفاز لإنتاج الأمونيا؟', '["النيتروجين والأكسجين","الميثان وثاني أكسيد الكربون","أول أكسيد الكربون وبخار الماء","النيتروجين والهيدروجين"]'::jsonb, 3, 30, 10, 'multi', 'تثبت العملية النيتروجين الجوي بتفاعله مع الهيدروجين لإنتاج الأمونيا. أثبت فريتز هابر المبدأ مخبريًا، وحوله كارل بوش وزملاؤه في BASF إلى عملية صناعية عالية الضغط؛ وكانت أساسًا لأسمدة رفعت الإنتاج الغذائي، وكذلك لمواد متفجرة.', 'الكيمياء الصناعية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'ما الفارق البنيوي الأشهر بين نموذجي الدائرة المتكاملة اللذين قدّمهما جاك كيلبي وروبرت نويس في بداياتها؟', '["استخدم كيلبي الأنابيب المفرغة، بينما استخدم نويس المرحلات","صنع كيلبي ذاكرة مغناطيسية، بينما صنع نويس معالجًا دقيقًا","كان نموذج كيلبي رقميًا فقط ونموذج نويس تناظريًا فقط","استخدم كيلبي الجرمانيوم ووصلات سلكية، بينما اقترح نويس السيليكون وعملية مستوية بوصلات معدنية على الرقاقة"]'::jsonb, 3, 35, 11, 'multi', 'برهن كيلبي سنة 1958 إمكان دمج المكونات على قطعة جرمانيوم، لكن نموذجه احتاج أسلاكًا خارجية دقيقة. جاء تصميم نويس السيليكوني المعتمد على العملية المستوية والوصلات المعدنية المطبوعة أكثر ملاءمة للتصنيع الكمي؛ لذا ينسب تاريخ الدائرة المتكاملة إلى مساهمتين مستقلتين متكاملتين.', 'الإلكترونيات الدقيقة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'أي سلسلة من الخطوات تعبّر بدقة عن دورة واحدة في تفاعل البوليميراز المتسلسل PCR؟', '["ترجمة RNA، ثم طي البروتين، ثم فصله كهربائيًا","فصل شريطي DNA بالحرارة، ثم ارتباط البوادئ، ثم استطالة السلاسل بإنزيم بوليميراز","قطع DNA بإنزيم تقييد، ثم لصقه، ثم إدخاله في خلية","نسخ DNA إلى RNA، ثم إزالة الإنترونات، ثم إضافة ذيل متعدد الأدينين"]'::jsonb, 1, 35, 12, 'multi', 'يضاعف PCR مقطعًا مستهدفًا دوريًا: التمسخ الحراري يفصل الشريطين، والتلدين يثبت بادئين يحددان الحدود، والاستطالة تنشئ DNA جديدًا. جعل البوليميراز المقاوم للحرارة، مثل Taq، تكرار الدورات آليًا دون إضافة إنزيم جديد كل مرة.', 'التقنية الحيوية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'لماذا كانت «الصورة 51» التي التقطها عمل روزاليند فرانكلين وريموند غوسلين مهمة في كشف بنية DNA؟', '["أثبتت مباشرة ترتيب جميع القواعد في الجينوم البشري","كشفت أن DNA بروتين مكوّن من أحماض أمينية","أظهر نمط حيود الأشعة السينية فيها سمات هندسية تدل على بنية حلزونية","أظهرت تضاعف الكروموسومات بالمجهر الإلكتروني الحي"]'::jsonb, 2, 35, 13, 'multi', 'أعطى نمط الحيود على هيئة X ومقاييسه دليلًا قويًا على اللولب وأبعاده. استفاد واتسون وكريك من بيانات فرانكلين وويلكنز وغيرها لبناء نموذج اللولب المزدوج؛ وعليه فالكشف ثمرة تراكم تجريبي ونمذجة شارك فيها عدة باحثين، لا لحظة فردية منفردة.', 'الوراثة والبنية الجزيئية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'ما الوظيفة الطبيعية التي ينتمي إليها نظام CRISPR-Cas9 قبل تحويله إلى أداة لتحرير الجينوم؟', '["آلية حقيقية النوى لإصلاح التيلوميرات","دفاع تكيفي في البكتيريا والعتائق ضد المادة الوراثية الغازية","مسار ميتوكوندري لتوليد ATP","نظام فيروسي لترجمة البروتين دون ريبوسومات"]'::jsonb, 1, 35, 14, 'multi', 'تحتفظ كائنات بدائية النوى بمقاطع من غزاة سابقين في مصفوفات CRISPR، وتستخدم RNA دليلاً مع بروتينات Cas للتعرف إلى التسلسلات الغازية وقطعها. بينت إيمانويل شاربنتييه وجنيفر دودنا إمكان برمجة Cas9 بدليل RNA ليقطع DNA في موضع مختار.', 'تحرير الجينوم');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'أي تطور تقني جعل بطاريات الليثيوم-أيون التجارية أكثر أمانًا من تصميم يعتمد على أنود الليثيوم المعدني؟', '["استخدام مادة مضيفة تتداخل فيها أيونات الليثيوم، مثل الكربون، بدل ترسيب معدن الليثيوم","استبدال الإلكتروليت بتيار من بخار الماء","إزالة الفاصل بين القطبين","تشغيل الخلية بتفاعل احتراق مباشر"]'::jsonb, 0, 35, 15, 'multi', 'أتاحت مواد التداخل انتقال أيونات الليثيوم ذهابًا وإيابًا بين قطبين من دون الحاجة إلى أنود من الليثيوم المعدني، الذي قد ينمّي تغصنات خطرة. بُني التطور على كاثود ويتنغهام، وجهد أعلى حققه غوديناف، وأنود كربوني عملي طوّره يوشينو.', 'تخزين الطاقة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'ما العقبة المادية التي أدى حلها إلى منح نوبل الفيزياء 2014 عن الصمام الثنائي الباعث للضوء الأزرق؟', '["إيجاد سلك تنغستن لا ينصهر في الفراغ","إنتاج طبقات نيتريد الغاليوم عالية الجودة وتحقيق تطعيم من النوع p بكفاءة","منع السيليكون النقي من امتصاص الضوء الأحمر","تبريد الزئبق إلى حالة التوصيل الفائق"]'::jsonb, 1, 35, 16, 'multi', 'ظل LED الأزرق الساطع صعبًا لأن نيتريد الغاليوم كان عسير النمو البلوري والتطعيم p. مكنت إنجازات أكاساكي وأمانو وناكامورا من وصلات فعالة تبعث الأزرق؛ وبإضافته إلى الأحمر والأخضر أمكن الضوء الأبيض عالي الكفاءة وتطبيقات العرض والإضاءة.', 'الضوئيات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'في نظام تحديد المواقع GPS، ماذا يحدث للساعة الذرية على القمر الصناعي مقارنة بساعة على سطح الأرض عند جمع أثري النسبية الخاصة والعامة؟', '["تتأخر إجمالًا بالمقدار نفسه الذي تتقدم به دائمًا","لا يتغير معدلها لأن التأثيرين ينعدمان تمامًا","تتوقف لحظة مرور القمر فوق خط الاستواء","تتقدم إجمالًا، لذلك يلزم تصحيح نسبي كي لا يتراكم خطأ الموقع"]'::jsonb, 3, 40, 17, 'multi', 'الحركة المدارية تجعل الساعة أبطأ وفق النسبية الخاصة، لكن وجود القمر في مجال جاذبية أضعف يجعلها أسرع وفق النسبية العامة، والأثر العام هو تقدم يقارب 38 ميكروثانية يوميًا. من دون التعويض يتضخم خطأ المسافة سريعًا لأن GPS يقيس أزمنة وصول الإشارات.', 'الملاحة الفضائية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'أي مبدأ فيزيائي يميز الليزر عن مصدر ضوء حراري عادي ويمنحه ضوءًا عالي الترابط والاتجاهية؟', '["التأين الحراري وحده داخل فتيلة معدنية","الانعكاس الكلي في منشور بلا وسط كسب","حيود الضوء الأبيض عبر محزوز فقط","الانبعاث المحفَّز مع تحقيق انقلاب سكاني داخل وسط الكسب"]'::jsonb, 3, 35, 18, 'multi', 'يحفز فوتونٌ ذرةً مثارة على إصدار فوتون مطابق في التردد والطور والاتجاه. وعندما يفوق عدد الجسيمات في الحالة المثارة عددها في الأدنى—الانقلاب السكاني—يتغلب التضخيم على الفقد، ويعزز التجويف البصري أنماطًا محددة لتكوين حزمة مترابطة.', 'الضوء والليزر');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'أي قرينة دفعت فيلهلم رونتغن إلى استنتاج وجود إشعاع نافذ جديد سنة 1895 أثناء تجاربه بأنبوب تفريغ مغطى؟', '["انحراف إبرة بوصلة قرب سلك يمر فيه تيار مستمر","ظهور خطوط طيفية للهيدروجين في لهب","توهج شاشة مطلية ببلاتينوسيانايد الباريوم بعيدًا عن الأنبوب رغم حجبه","سقوط قطرة زيت مشحونة بين لوحين"]'::jsonb, 2, 35, 19, 'multi', 'لاحظ رونتغن فلورة شاشة كيميائية مع أن أنبوب الأشعة المهبطية كان محجوبًا بورق أسود، فاستدل على أشعة مجهولة قادرة على النفاذ وسماها X. سرعان ما أظهر اختلاف امتصاصها بين العظم والأنسجة قيمتها في التصوير الطبي.', 'التصوير الطبي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'ما النتيجة التي ميّزت تجربة هنري بيكريل بأملاح اليورانيوم عن فرضيته الأولى التي ربطت الإشعاع بضوء الشمس؟', '["توقف الإشعاع كليًا حين غابت الشمس","تحولت أملاح اليورانيوم إلى أشعة مهبطية في فراغ","اسودّت ألواح التصوير المحفوظة في الظلام، ما دل على إشعاع تلقائي من المادة","ظهر الإشعاع فقط بعد تسخين الأملاح حتى الانصهار"]'::jsonb, 2, 35, 20, 'multi', 'كان بيكريل يختبر صلة محتملة بين الفسفرة والأشعة السينية. لكن ألواحًا ملفوفة ومخزنة في درج اسودّت بقوة قرب مركب اليورانيوم من دون تعريض شمسي، فدل ذلك على أن الإشعاع يصدر تلقائيًا؛ ووسعت ماري وبيير كوري دراسة الظاهرة وسمّياها النشاط الإشعاعي.', 'النشاط الإشعاعي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'كيف ساعد مجهر أنطوني فان ليفينهوك ذو العدسة الواحدة على فتح عالم الأحياء الدقيقة رغم بساطة تصميمه؟', '["حققت عدسته الصغيرة الجيدة التكبير والدقة الكافيين لرؤية كائنات دقيقة حية","استخدم حزمة إلكترونات في فراغ لرؤية الذرات","صبغ الخلايا بصبغات فلورية وأثارها بليزر","كوّن صورًا مقطعية من صدى الموجات فوق الصوتية"]'::jsonb, 0, 35, 21, 'multi', 'صنع ليفينهوك عدسات مفردة شديدة التقوس ومصقولة بعناية، وقد تفوقت بصريًا في بعض الاستخدامات على المجاهر المركبة المبكرة التي عانت زيغًا شديدًا. بها وصف الأوليات والبكتيريا وغيرها؛ ولم يكن المخترع الوحيد للمجهر، بل مطورًا بارزًا لاستخدامه العلمي.', 'المجهر والأحياء الدقيقة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'أي تركيب بين تقنيتين كان جوهر «التلغراف اللاسلكي» المبكر لدى ماركوني؟', '["نقل الصوت المستمر في ألياف زجاجية","ترميز الرسائل بنبضات وإرسالها بموجات كهرومغناطيسية من دون سلك","تحويل الصور إلى مسح إلكتروني عبر قمر صناعي","تخزين الحروف على بطاقات مثقبة ثم شحنها بالبريد"]'::jsonb, 1, 35, 22, 'multi', 'جمع النظام المبكر إرسال الشرر لموجات راديوية وكاشفًا وهوائيًا مع لغة النبضات التلغرافية، فانتقلت رسائل مورس بلا كابل. استند ماركوني إلى اكتشافات ماكسويل وهرتز وأعمال عدة مجربين، وكانت مساهمته الأساسية هندسة منظومة اتصال عملية بعيدة المدى وتسويقها.', 'الاتصالات اللاسلكية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'ما الابتكار التنظيمي الذي جعل حاوية الشحن المعيارية تغيّر التجارة العالمية، وليس مجرد كونها صندوقًا معدنيًا؟', '["اشتراط فتح كل صندوق في كل ميناء لإعادة الجرد","إمكان نقل الوحدة نفسها بين الشاحنة والقطار والسفينة دون تفريغ محتواها قطعةً قطعة","قصر الحاويات على نوع واحد من السفن دون نقل بري","استبدال الرافعات نهائيًا بعمال المناولة اليدوية"]'::jsonb, 1, 35, 23, 'multi', 'جوهر الحاوية هو النقل متعدد الوسائط: وحدة موحدة تُغلق عند المنشأ وتنتقل بين وسائل النقل برافعات وتجهيزات متوافقة. خفض ذلك وقت الرسو والمناولة والتلف والسرقة. دفع مالكوم ماكلين تطبيق النظام تجاريًا، ثم جعل التقييس الدولي الشبكة قابلة للتوسع عالميًا.', 'النقل واللوجستيات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_40, 'في المرحلة النهائية من استئصال الجدري عالميًا، ما الاستراتيجية التي استكملت التطعيم الواسع وكانت حاسمة في قطع سلاسل العدوى؟', '["الترصد والاحتواء بتحديد الحالات وتطعيم المخالطين حولها","استخدام المضادات الحيوية لجميع السكان","إبادة الحشرات الناقلة بالمبيدات","عزل الفيروس عبر تنقية مياه الشرب"]'::jsonb, 0, 35, 24, 'multi', 'إلى جانب حملات التطعيم، اعتمد البرنامج المكثف البحث النشط عن الحالات والتحقيق السريع فيها وتطعيم المخالطين وتكوين حلقات مناعة حول البؤر. كان الجدري ينتقل بين البشر مباشرة، لا عبر حشرة أو ماء، وأعلنت جمعية الصحة العالمية استئصاله سنة 1980 بعد آخر حالة طبيعية في 1977.', 'الصحة العامة');
  END IF;
END $$;



DO $$
DECLARE
  v_lib_id_41 uuid;
BEGIN
  SELECT id INTO v_lib_id_41 FROM quizzes WHERE title = 'أرقام قياسية وحقائق غرائب العالم' LIMIT 1;
  IF v_lib_id_41 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('أرقام قياسية وحقائق غرائب العالم', 'معلومات عامة', '', 'medium_high', 'ar', true)
    RETURNING id INTO v_lib_id_41;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'أي حيوان تؤكد الإدارة الوطنية للمحيطات والغلاف الجوي NOAA أنه أكبر حيوان عاش على الأرض، متجاوزًا حتى أضخم الديناصورات المعروفة؟', '["حوت الزعنفة","قرش الحوت","الأرجنتينوصور","الحوت الأزرق"]'::jsonb, 3, 25, 0, 'multi', 'الحوت الأزرق هو أكبر حيوان معروف عاش على الأرض؛ قد يتجاوز طوله 30 مترًا وتبلغ كتلته نحو 180 طنًا أو أكثر في بعض التقديرات. قرش الحوت أكبر الأسماك، لكنه أصغر كثيرًا، والأرجنتينوصور من أضخم الديناصورات البرية لا أضخم الحيوانات مطلقًا.', 'سجلات الحيوان');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'إذا عُرّفت الصحراء بقلة الهطول لا بارتفاع الحرارة، فما أكبر صحراء على الأرض مساحةً؟', '["الصحراء الكبرى","القارة القطبية الجنوبية","صحراء غوبي","صحراء العرب"]'::jsonb, 1, 25, 1, 'multi', 'القارة القطبية الجنوبية صحراء قطبية لأن هطولها شديد الانخفاض، وتبلغ مساحتها نحو 14 مليون كيلومتر مربع؛ لذلك تتجاوز الصحراء الكبرى، وهي أكبر صحراء حارة. الخلط الشائع سببه مساواة الصحراء بالرمال والحرارة بدل معيار الجفاف.', 'غرائب الجغرافيا');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'في أي خندق محيطي تقع «تشالنجر ديب»، أعمق نقطة معروفة في محيطات الأرض؟', '["خندق تونغا","خندق ماريانا","خندق بورتوريكو","خندق اليابان"]'::jsonb, 1, 25, 2, 'multi', 'تقع تشالنجر ديب في الطرف الجنوبي من خندق ماريانا في غرب المحيط الهادئ. تختلف تقديرات العمق قليلًا باختلاف المسح ونموذج سرعة الصوت، لذلك السؤال يطلب الموقع لا رقمًا زائف الدقة؛ وتضعها قياسات NOAA قرب 10.9 كيلومتر تحت سطح البحر.', 'أعماق الأرض');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'بعد القياس المشترك الذي أعلنته نيبال والصين في ديسمبر 2020، ما الارتفاع الرسمي الجديد لقمة إيفرست فوق مستوى البحر؟', '["8,848.86 مترًا","8,611 مترًا","8,850.50 مترًا","8,586 مترًا"]'::jsonb, 0, 25, 3, 'multi', 'أعلنت نيبال والصين 8,848.86 مترًا ارتفاعًا رسميًا مشتركًا لإيفرست، ويشمل القياس الغطاء الثلجي على القمة. أما 8,611 مترًا فهو ارتفاع K2، و8,586 مترًا ارتفاع كانغشينجونغا.', 'القمم والقياس');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'أي نظام كهوف كان الأطول المعروف عالميًا وفق تحديث خدمة المتنزهات الوطنية الأميركية في نوفمبر 2024، بأكثر من 426 ميلًا من الممرات الممسوحة؟', '["كهف الجوهرة","نظام ساك أكتون","كهف الماموث","كهف أوبتيميستيتشنا"]'::jsonb, 2, 25, 4, 'multi', 'بلغت الممرات الممسوحة في نظام كهف الماموث بكنتاكي أكثر من 426 ميلًا وفق تحديث 7 نوفمبر 2024، ما يجعله أطول نظام كهوف معروف بفارق كبير. الرقم قابل للزيادة لأن الاستكشاف والمسح مستمران، ولذلك ثُبّت تاريخ المرجع.', 'الكهوف');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'أي نبات يحمل عادةً الرقم القياسي لأكبر زهرة مفردة، لا لأكبر نورة مركبة من أزهار كثيرة؟', '["رافليسيا أرنولدي Rafflesia arnoldii","التايتان أروم Amorphophallus titanum","فيكتوريا أمازونيكا","الباوباب الإفريقي"]'::jsonb, 0, 30, 5, 'multi', 'رافليسيا أرنولدي تنتج أكبر زهرة مفردة، وقد تقارب مترًا عرضًا. أما التايتان أروم فبنيته الضخمة نورة: محور يحمل عددًا كبيرًا من الأزهار الصغيرة تحيط به قنابة، ولذلك لا يصح منحه سجل «الزهرة المفردة».', 'غرائب النبات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'إلى أي جنس تنتمي أصغر النباتات المزهرة في العالم، وهي نباتات مائية دقيقة قد لا يتجاوز بعضها رأس دبوس؟', '["Azolla","Wolffia","Lemna","Selaginella"]'::jsonb, 1, 25, 6, 'multi', 'تضم Wolffia نباتات عدسية طافية شديدة الصغر تُعد أصغر كاسيات البذور. تبدو بلا جذور أو أوراق تقليدية واضحة، لكنها تنتج أزهارًا وثمارًا؛ أما Azolla فسرخس مائي وليست نباتًا مزهرًا.', 'غرائب النبات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'ما السلوك الذي يمنح الشاهين سجل أسرع حيوان في القياسات الشائعة، بسرعات تتجاوز 300 كم/س؟', '["عدوه الأفقي فوق اليابسة","هجرته مع الرياح الخلفية","سباحته تحت سطح الماء","غوصه الانقضاضي نحو الفريسة"]'::jsonb, 3, 25, 7, 'multi', 'يسجل الشاهين سرعته القصوى في الانقضاض الحاد من ارتفاع، لا في الطيران الأفقي المستوي. يحول الارتفاع إلى سرعة ويضم جناحيه لتقليل السحب؛ لذلك لا يجوز مقارنة هذا السجل مباشرة بسرعة عدو الفهد على الأرض.', 'سرعات الحيوان');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'بحسب أرشيف المنظمة العالمية للأرصاد الجوية كما كان في 31 يوليو 2025، أين سُجلت أعلى درجة حرارة هواء معترف بها عالميًا: 56.7°م في 10 يوليو 1913؟', '["قبلي في تونس","تربت في إسرائيل","فرنِس كريك في وادي الموت بالولايات المتحدة","متربة في الكويت"]'::jsonb, 2, 30, 8, 'multi', 'يسجل أرشيف WMO الرسمي 56.7°م في فرنِس كريك، المعروف تاريخيًا باسم Greenland Ranch، في كاليفورنيا يوم 10 يوليو 1913. توجد مناقشات علمية حول قياسات قديمة، لكن السؤال يحدد صراحة السجل الذي تعترف به WMO حتى 31 يوليو 2025.', 'السجلات المناخية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'أي نزاع يُذكر عادةً بوصفه أقصر حرب مسجلة، إذ انتهى في 27 أغسطس 1896 بعد أقل من ساعة تقريبًا؟', '["حرب الخنزير","حرب الأيام الستة","الحرب الإنجليزية الزنجبارية","الحرب الإنجليزية الفارسية"]'::jsonb, 2, 25, 9, 'multi', 'اندلع القصف البريطاني لقصر زنجبار صباح 27 أغسطس 1896 وانتهت المقاومة بعد نحو 38 إلى 45 دقيقة بحسب طريقة حساب البداية والنهاية. لذلك تُوصف الحرب الإنجليزية الزنجبارية عادةً بأنها الأقصر، مع إبقاء المدة نطاقًا بدل رقم وحيد مختلف عليه.', 'سجلات التاريخ');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'سجلت محطة فوستوك في أنتاركتيكا أدنى حرارة هواء مقاسة مباشرة ومعترفًا بها من WMO، وهي −89.2°م. في أي تاريخ حدث ذلك؟', '["24 أغسطس 1960","21 يوليو 1983","10 أغسطس 2010","31 يوليو 2025"]'::jsonb, 1, 30, 10, 'multi', 'قيس السجل بمحطة فوستوك في 21 يوليو 1983. وتوجد تقديرات ساتلية لدرجات سطح ثلجي أبرد، لكنها ليست قياسًا معياريًا لحرارة الهواء في محطة أرصاد؛ لذلك يبقى سجل WMO للهواء −89.2°م.', 'السجلات المناخية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'يحمل موقع فوك-فوك في جزيرة لا ريونيون سجل WMO لأكبر مطر خلال 24 ساعة: 1,825 ملم في يناير 1966. بأي إعصار مداري ارتبط الحدث؟', '["إعصار هايان","إعصار دينيس","إعصار نانسي","إعصار فريدي"]'::jsonb, 1, 35, 11, 'multi', 'هطل 1,825 ملم في 24 ساعة عند فوك-فوك يومي 7 و8 يناير 1966 أثناء الإعصار المداري دينيس. تضاريس لا ريونيون الجبلية تعزز صعود الهواء الرطب، ولهذا تظهر الجزيرة في عدة سجلات عالمية لتراكم المطر خلال مدد متعددة.', 'السجلات المناخية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'أي عامل يجعل هبة بارو آيلاند الأسترالية البالغة 113.2 م/ث في 10 أبريل 1996 سجلًا عالميًا لـ«أقصى هبة رياح» لدى WMO، مع استبعاد الأعاصير القمعية؟', '["قيسَت فوق قمة إيفرست","استُنتجت من أضرار المباني فقط","كانت متوسطًا شهريًا لا هبة لحظية","ارتبطت بإعصار مداري وسجلها جهاز قياس سطحي"]'::jsonb, 3, 35, 12, 'multi', 'سجل جهاز الأنيمومتر في بارو آيلاند هبة 113.2 م/ث، أي نحو 408 كم/س، أثناء الإعصار المداري أوليفيا. يفصل أرشيف WMO هذه الفئة عن سرعات الأعاصير القمعية التي تُقاس أو تُستنتج بمنهج مختلف.', 'السجلات المناخية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'أي إعصار مداري يحمل سجل أدنى ضغط جوي عند مستوى البحر خارج الأعاصير القمعية، بقيمة 870 هكتوباسكال في 12 أكتوبر 1979؟', '["الإعصار باتريشيا","الإعصار ويلما","الإعصار نانسي","الإعصار تيب"]'::jsonb, 3, 30, 13, 'multi', 'وصل الضغط المركزي في عين الإعصار الفائق تيب إلى 870 هكتوباسكال، وهو أدنى ضغط سطحي معتمد عالميًا في هذا التصنيف. باتريشيا سجل شدة رياح استثنائية في النصف الغربي، لكنه لم يخفض الضغط إلى قيمة تيب.', 'الأعاصير المدارية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'في يوليو 2025 صدّقت WMO رقمًا قياسيًا جديدًا لأطول ومضة برق مفردة: 829 كم. بين أي منطقتين امتدت تقريبًا؟', '["من فلوريدا إلى كوبا","من شرق تكساس إلى قرب كانساس سيتي","من الأرجنتين إلى أوروغواي","من فرنسا إلى إيطاليا"]'::jsonb, 1, 35, 14, 'multi', 'وقعت الومضة في أكتوبر 2017 وامتدت 829 كم من شرق تكساس إلى قرب كانساس سيتي، لكن تحليل الأقمار الصناعية اللاحق أتاح توثيقها والتصديق عليها في 31 يوليو 2025. ذكر باريس والبندقية في بيان WMO مجرد مقارنة للمسافة، لا موقع الومضة.', 'البرق');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'اعتمدت WMO الإعصار المداري فريدي بوصفه الأطول عمرًا. كم يومًا بلغ عمره الإجمالي وفق التقييم المنشور في يوليو 2024؟', '["36 يومًا","24 يومًا","31 يومًا","42 يومًا"]'::jsonb, 0, 30, 15, 'multi', 'خلص تقييم WMO إلى أن فريدي دام 36 يومًا بحالة عاصفة مدارية، من 4 فبراير إلى 14 مارس 2023، متجاوزًا الرقم السابق للإعصار جون. كما عبر كامل المحيط الهندي الجنوبي ومر بمراحل ضعف وإعادة اشتداد.', 'الأعاصير المدارية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'وفق أرشيف WMO، أين سقطت أثقل حبّة بَرَد موثقة عالميًا، بكتلة 1.02 كغ، في 14 أبريل 1986؟', '["غوبالغنج في بنغلاديش","فيفيان في داكوتا الجنوبية","كوفينغتون في نبراسكا","بارو آيلاند في أستراليا"]'::jsonb, 0, 35, 16, 'multi', 'سجلت غوبالغنج في بنغلاديش حبّة برد كتلتها 1.02 كغ. أما حبّة فيفيان الأميركية فمشهورة بسجل أميركي للقطر (20.3 سم) والمحيط، وهو تصنيف مختلف؛ لذا يحدد السؤال «الأثقل عالميًا» لا «الأكبر قطرًا في الولايات المتحدة».', 'البَرَد');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'صُوِّرت أعمق سمكة معروفة حيةً سنة 2022 على عمق 8,336 مترًا في خندق إيزو-أوغاساوارا. إلى أي جنس تنتمي؟', '["Himantolophus","Macropinna","Pseudoliparis","Latimeria"]'::jsonb, 2, 35, 17, 'multi', 'التقطت كاميرا سمكة حلزونية من جنس Pseudoliparis على عمق 8,336 مترًا؛ ولم تُصَد العينة المصورة، لذلك عُرّفت إلى مستوى الجنس. وفي الرحلة نفسها صيدت عينات من Pseudoliparis belyaevi على عمق 8,022 مترًا، وهو رقم قياسي منفصل للصيد.', 'أحياء الأعماق');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'قدّرت دراسة التأريخ بالكربون المشع لعدسة العين عمر أكبر قرش غرينلاند في عينتها بنحو 392 سنة. ما هامش عدم اليقين المنشور لهذا التقدير؟', '["±120 سنة","±12 سنة","±50 سنة","±240 سنة"]'::jsonb, 0, 40, 18, 'multi', 'كان التقدير 392 ± 120 سنة، وهو هامش واسع يبين أن الرقم ليس «عمرًا دقيقًا» للفرد. استخدم الباحثون الكربون المشع في بروتينات نواة عدسة العين التي تتكون مبكرًا ولا تتجدد، وخلصوا إلى أن النوع أطول الفقاريات عمرًا المعروفة.', 'طول العمر الحيواني');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'في دراسة تتبع جغرافي، قطع خرشنة قطبية مسارًا سنويًا قياسيًا تجاوز 96 ألف كم. إلى أي منطقة شتوية توجه الطائر من جزر فارن البريطانية؟', '["بحر بيرنغ","بحر ويدل في أنتاركتيكا","مدغشقر","جزر غالاباغوس"]'::jsonb, 1, 40, 19, 'multi', 'تعقب الباحثون خرشنة قطبية من جزر فارن إلى بحر ويدل في أنتاركتيكا ثم عودتها، فبلغت الرحلة أكثر من 96 ألف كم بسبب المسار المتعرج واستغلال الرياح ومناطق الغذاء. المسافة الفعلية أكبر كثيرًا من خط مستقيم بين منطقتي التكاثر والشتاء.', 'هجرة الطيور');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'ما العمق النهائي الذي بلغه بئر كولا فائق العمق SG-3 في روسيا سنة 1989، محافظًا على سجل أعمق اختراق رأسي اصطناعي للقشرة؟', '["10,911 مترًا","11,034 مترًا","15,000 متر","12,262 مترًا"]'::jsonb, 3, 35, 20, 'multi', 'وصل فرع SG-3 إلى 12,262 مترًا. قد تكون آبار نفط حديثة أطول «طولًا مقاسًا» لأنها تنحرف أفقيًا، لكن كولا يحتفظ بسجل العمق الرأسي؛ وهذه التفرقة بين طول مسار البئر والعمق الرأسي تمنع المقارنة المضللة.', 'الهندسة الجيولوجية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'أي دولة تتصدر عادةً عدد المناطق الزمنية إذا احتُسبت أقاليمها المنتشرة وراء البحار، بواقع 12 منطقة قياسية و13 في جزء من السنة؟', '["روسيا","الولايات المتحدة","فرنسا","المملكة المتحدة"]'::jsonb, 2, 35, 21, 'multi', 'تنتشر أقاليم فرنسا من الكاريبي إلى المحيطين الهندي والهادئ، فتغطي 12 فرقًا معياريًا عن UTC، وتصبح 13 عند احتساب التوقيت الصيفي في سان بيير وميكلون. روسيا تغطي 11 منطقة زمنية متصلة تقريبًا، لذلك لا تتصدر بهذا التعريف.', 'غرائب السياسة والجغرافيا');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'دام حكم لويس الرابع عشر 72 سنة و110 أيام، وهو الأطول الموثق لملك ذي سيادة. ما العامل الذي يفسر إمكان بلوغ هذه المدة الاستثنائية؟', '["تولّى العرش وهو في الرابعة من عمره","حكم دولتين بالتناوب فجمعت المدتان","أُعيد احتساب سنوات الوصاية بعد وفاته","تنازل ثم عاد إلى العرش ثلاث مرات"]'::jsonb, 0, 35, 22, 'multi', 'أصبح لويس الرابع عشر ملك فرنسا في 14 مايو 1643 وهو طفل في الرابعة، وظل ملكًا حتى وفاته في 1 سبتمبر 1715. شملت مدة الحكم سنوات الوصاية لأنها بدأت قانونيًا عند توليه العرش، حتى وإن لم يمارس الحكم الشخصي منذ اليوم الأول.', 'سجلات الملوك');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'في إحصاءات مكتبة الكونغرس، لماذا لا يساوي عدد «المواد» في مجموعتها عدد الكتب المطبوعة؟', '["لأنها تعد الكتب الرقمية مرتين دائمًا","لأن الصحف تستبعد كليًا من الإحصاء","لأن كل صفحة في الكتاب تُعد مادة مستقلة","لأن مفهوم المواد يشمل تسجيلات وصورًا وخرائط ومخطوطات ومواد موسيقية إلى جانب الكتب"]'::jsonb, 3, 35, 23, 'multi', 'تصف مكتبة الكونغرس نفسها بأنها أكبر مكتبة في العالم استنادًا إلى مجموعة تتجاوز 178 مليون مادة، لكن «المادة» وحدة مقتنيات متنوعة لا مرادف لكتاب: تشمل تسجيلات وصورًا وخرائط ومخطوطات ونوتات موسيقية وغيرها. لذا فإن تحويل الرقم إلى «178 مليون كتاب» خطأ شائع.', 'المعرفة والمكتبات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_41, 'كشف التحليل الجيني في خليج شارك بأستراليا أن مرجًا بحريًا يغطي نحو 200 كم² هو نبات واحد ممتد نسليًا. ما نوعه؟', '["Zostera marina","Macrocystis pyrifera","Posidonia australis","Thalassia testudinum"]'::jsonb, 2, 40, 24, 'multi', 'أظهرت البصمات الجينية أن عينات Posidonia australis المتباعدة في خليج شارك تنتمي إلى نسخة وراثية واحدة نمت بجذاميرها على مساحة تقارب 200 كم². وهي نبات مزهر بحري وليست طحلبًا عملاقًا؛ ويختلف سجل «أكبر كائن» باختلاف معيار المساحة أو الكتلة أو الاتصال النسلي.', 'غرائب النبات');
  END IF;
END $$;



DO $$
DECLARE
  v_lib_id_42 uuid;
BEGIN
  SELECT id INTO v_lib_id_42 FROM quizzes WHERE title = 'الغزوات والمعاهدات الإسلامية' LIMIT 1;
  IF v_lib_id_42 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('الغزوات والمعاهدات الإسلامية', 'إسلاميات', '', 'high', 'ar', true)
    RETURNING id INTO v_lib_id_42;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_42, 'كان خروج المسلمين إلى بدر مرتبطًا أولًا بعير قريش العائدة من الشام. من كان يقود تلك القافلة وتمكن من تغيير طريقها والنجاة بها؟', '["أبو سفيان بن حرب","صفوان بن أمية","عكرمة بن أبي جهل","سهيل بن عمرو"]'::jsonb, 0, 30, 0, 'multi', 'كان أبو سفيان قائد العير، فاستطلع الأخبار وحوّل القافلة إلى طريق الساحل حتى نجت، بينما مضى جيش قريش إلى بدر. يفسر ذلك قوله تعالى إن المسلمين ودّوا أن تكون لهم إحدى الطائفتين: العير أو النفير.', 'غزوة بدر');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_42, 'ما المهمة التي كلّف بها النبي ﷺ عبدَ الله بن جبير ومن معه يوم أُحد، بحسب حديث البراء بن عازب؟', '["الثبات على موضع الرماة وحماية ظهر الجيش ولو رأوا النصر أو الهزيمة","حراسة مدخل المدينة ومنع الإمدادات","ملاحقة المنسحبين حتى مكة","التفاوض مع قريش قبل بدء القتال"]'::jsonb, 0, 30, 1, 'multi', 'أمّر النبي ﷺ عبد الله بن جبير على الرماة وأمرهم ألا يتركوا موضعهم سواء رأوا المسلمين منتصرين أو مصابين. لما ترك أكثرهم الموقع انكشف ظهر الجيش، وهو محور تفسير التحول الميداني في أُحد.', 'غزوة أُحد');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_42, 'أي سورة وصفت اجتماع الأحزاب حول المدينة واضطراب الأبصار وبلوغ القلوب الحناجر؟', '["سورة الأنفال","سورة الأحزاب","سورة الحشر","سورة الفتح"]'::jsonb, 1, 25, 2, 'multi', 'تسجل سورة الأحزاب مشهد الحصار والابتلاء في الآيات 9–22، ومنها وصف مجيء الجموع من فوق المسلمين ومن أسفل منهم وزيغ الأبصار وبلوغ القلوب الحناجر. أما الأنفال فمحورها الأبرز بدر، والحشر يتناول بني النضير.', 'غزوة الخندق');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_42, 'ما الشرط الزمني المتعلق بالعمرة في صلح الحديبية كما يظهر في حديث المسور بن مخرمة ومروان؟', '["يدخل المسلمون مكة في عامهم نفسه ويقيمون ثلاثة أيام","تؤجل العمرة خمس سنوات كاملة","تكون العمرة التالية بلا سلاح ولا هدي","يرجع المسلمون ذلك العام ويدخلون مكة في العام التالي"]'::jsonb, 3, 30, 3, 'multi', 'قضى الصلح بأن يرجع المسلمون من الحديبية من غير دخول مكة ذلك العام، ثم يأتوا في العام التالي. لذلك سميت العمرة التالية عمرة القضاء، وكان الرجوع الفوري من أكثر بنود الصلح مشقة على بعض الصحابة.', 'صلح الحديبية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_42, 'لمن أعطى النبي ﷺ الراية يوم خيبر بعد أن أخبر أنه سيعطيها رجلًا يحب الله ورسوله ويحبه الله ورسوله؟', '["الزبير بن العوام","علي بن أبي طالب","سعد بن أبي وقاص","أبو عبيدة بن الجراح"]'::jsonb, 1, 25, 4, 'multi', 'دعا النبي ﷺ علي بن أبي طالب، فمسح على عينيه حين كان يشتكيهما، ثم دفع إليه الراية وأرشده إلى الدعوة قبل القتال. ورد أصل الخبر في الصحيحين، وهو من أشهر الوقائع الثابتة في خيبر.', 'غزوة خيبر');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_42, 'كيف رتب النبي ﷺ قيادة جيش مؤتة قبل خروجه، وفق رواية عبد الله بن عمر؟', '["خالد بن الوليد، ثم زيد بن حارثة، ثم جعفر","جعفر بن أبي طالب، ثم خالد بن الوليد، ثم أسامة بن زيد","زيد بن حارثة، ثم جعفر بن أبي طالب، ثم عبد الله بن رواحة","عبد الله بن رواحة، ثم زيد بن حارثة، ثم أبو عبيدة"]'::jsonb, 2, 30, 5, 'multi', 'عيّن النبي ﷺ زيدًا أولًا، فإن أصيب فجعفر، فإن أصيب فعبد الله بن رواحة. استشهد الثلاثة بهذا الترتيب، ثم أخذ خالد بن الوليد الراية من غير أن يكون ضمن التسلسل المسمّى ابتداءً.', 'غزوة مؤتة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_42, 'ما العامل الذي نهى القرآن عن الاغترار به عند ذكر بداية يوم حنين؟', '["حصانة المدينة التي ظنوا أنها تمنع الهزيمة","كثرة العدد التي أعجبت المسلمين فلم تغن عنهم","تحالف الروم الذي اعتقدوا أنه دائم","وفرة السلاح البحري لدى المسلمين"]'::jsonb, 1, 25, 6, 'multi', 'نصت الآية على أن كثرة المسلمين أعجبتهم يوم حنين، لكنها لم تدفع عنهم شدة المفاجأة، فضاقت عليهم الأرض وولوا مدبرين، ثم أنزل الله سكينته. الدرس القرآني يربط النصر بالتأييد لا بمجرد التفوق العددي.', 'غزوة حنين');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_42, 'بأي وصف قرآني اشتهرت الظروف الشاقة التي خرج فيها النبي ﷺ والمهاجرون والأنصار إلى تبوك؟', '["يوم الفرقان","يوم الجمع","ليلة الإسراء","ساعة العسرة"]'::jsonb, 3, 25, 7, 'multi', 'سمت سورة التوبة الظرف «ساعة العسرة» عند ذكر توبة الله على النبي والمهاجرين والأنصار الذين اتبعوه فيها. يرتبط الوصف بما صاحب تبوك من بعد المسافة والحر وقلة الزاد والركائب.', 'غزوة تبوك');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_42, 'في سياق بدر، ما المقصود بـ«إحدى الطائفتين» في قوله تعالى: ﴿وإذ يعدكم الله إحدى الطائفتين أنها لكم﴾؟', '["الأوس أو الخزرج","قريظة أو النضير","الروم أو الفرس","عير قريش أو جيشها الخارج للقتال"]'::jsonb, 3, 35, 8, 'multi', 'تفسر كتب التفسير والسيرة الطائفتين بالعير التجارية التي يقودها أبو سفيان والنفير، أي القوة القرشية التي خرجت لحمايتها. كان المسلمون يميلون إلى العير لقلة شوكتها، وأراد الله وقوع المواجهة التي أظهرت الحق.', 'غزوة بدر');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_42, 'أي آية من سورة آل عمران فسرت جانبًا من الخلل الذي وقع في أُحد بذكر التنازع والعصيان بعد أن أرى الله المسلمين ما يحبون؟', '["آية 123","آية 152","آية 159","آية 173"]'::jsonb, 1, 35, 9, 'multi', 'الآية 152 تقول: ﴿حتى إذا فشلتم وتنازعتم في الأمر وعصيتم من بعد ما أراكم ما تحبون﴾، ثم تذكر اختلاف الإرادة بين طلب الدنيا والآخرة. وهي النص القرآني الأوضح اتصالًا بمخالفة طائفة الرماة للأمر في أُحد.', 'غزوة أُحد');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_42, 'بحسب رواية السيرة المشهورة، أي تدبير دفاعي غير مألوف لدى العرب أشار به سلمان الفارسي عند قدوم الأحزاب؟', '["إغراق الطرق المحيطة بالمدينة","إخلاء المدينة والقتال من خيبر","حفر خندق في الجهة المكشوفة من المدينة","بناء أبراج خشبية متنقلة"]'::jsonb, 2, 35, 10, 'multi', 'تنسب كتب السيرة إلى سلمان الفارسي اقتراح الخندق، وهي وسيلة عرفها من قتال الفرس ولم تكن من أساليب العرب المعتادة. صيغ السؤال بعبارة «رواية السيرة المشهورة» لأن نسبة الاقتراح التفصيلية تُروى في مصادر السيرة، لا في حديث متفق عليه مستقل بهذا اللفظ.', 'غزوة الخندق');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_42, 'ما الحدث المباشر الذي ارتبط ببيعة الرضوان في الحديبية وفق روايات السيرة والمغازي؟', '["شيوع خبر مقتل عثمان بن عفان الذي أُرسل إلى مكة","وصول خبر استشهاد قادة مؤتة","نقض بني بكر هدنة الحديبية","منع قريش خالد بن الوليد من العودة إلى مكة"]'::jsonb, 0, 35, 11, 'multi', 'أرسل النبي ﷺ عثمان إلى مكة للتفاوض، ثم شاع أنه قُتل، فدعا أصحابه إلى البيعة تحت الشجرة. ثبتت البيعة وفضل أهلها في القرآن والصحيح، أما ربطها بتفصيل إشاعة قتل عثمان فمذكور في روايات السيرة والمغازي.', 'بيعة الرضوان');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_42, 'عند كتابة وثيقة الحديبية، ما العبارة التي اعترض سهيل بن عمرو على إثباتها في صدر الوثيقة بحسب حديث البراء؟', '["محمد رسول الله","قريش أهل الحرم","علي بن أبي طالب كاتب الصلح","الهدنة عشر سنين"]'::jsonb, 0, 35, 12, 'multi', 'اعترض سهيل على كتابة «محمد رسول الله» محتجًا بأن الإقرار بالرسالة كان سينهي موضع النزاع، وطلب «محمد بن عبد الله». امتنع علي أولًا عن محو العبارة تعظيمًا، فدل النبي ﷺ على موضعها فمحاها، وأُتم الصلح.', 'صلح الحديبية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_42, 'أي موقف وقع أثناء إبرام صلح الحديبية وجسّد فورًا صعوبة بند إعادة من يأتي من قريش إلى المسلمين؟', '["عودة عثمان بن عفان من الحبشة","إسلام أبي سفيان أمام العباس","خروج أبي بصير قبل بدء المفاوضات","وصول أبي جندل بن سهيل مقيدًا وطلب سهيل إعادته"]'::jsonb, 3, 35, 13, 'multi', 'وصل أبو جندل بن سهيل يرسف في قيوده بعد الاتفاق على أصل الصلح، فطالب أبوه سهيل بأن يكون أول من يرد وفق الشرط. أعاده النبي ﷺ وفاءً بالعهد، مع تسليته ووعده بأن يجعل الله له وللمستضعفين فرجًا.', 'صلح الحديبية');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_42, 'كيف تعامل النبي ﷺ مع أرض خيبر بعد فتحها وفق حديث ابن عمر؟', '["قسم جميع النخيل فورًا ثم أخلى السكان في اليوم نفسه","جعل محصولها كله وقفًا على قريش","ترك أهلها يعملون فيها مقابل شطر ما يخرج منها من ثمر أو زرع","منع زراعتها وأبقاها منطقة عسكرية"]'::jsonb, 2, 35, 14, 'multi', 'عامل النبي ﷺ أهل خيبر على أن يعملوا الأرض من أموالهم ولهم شطر الثمر أو الزرع. تكشف الواقعة أن نتائج الفتح لم تقتصر على القتال، بل شملت ترتيبًا اقتصاديًا لإدارة الأرض والإنتاج.', 'غزوة خيبر');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_42, 'أي تسلسل يطابق الأخبار النبوية التي أبلغ بها النبي ﷺ عن قادة مؤتة قبل وصول الخبر المعتاد من الميدان؟', '["أُصيب جعفر ثم زيد ثم ابن رواحة، وأخذ الراية أسامة","أُصيب زيد ثم ابن رواحة ثم جعفر، وأخذ الراية أبو عبيدة","أُصيب خالد ثم زيد ثم جعفر، وعادت الراية إلى ابن رواحة","أُصيب زيد ثم جعفر ثم ابن رواحة، ثم أخذ الراية خالد بن الوليد"]'::jsonb, 3, 40, 15, 'multi', 'نعى النبي ﷺ زيدًا ثم جعفرًا ثم ابن رواحة، وأخبر أن خالد بن الوليد أخذ الراية بعدهم حتى فتح الله على الجيش. يختبر السؤال التفريق بين ترتيب القيادة المسمى ابتداءً وبين تولي خالد بعد استشهاد القادة الثلاثة.', 'غزوة مؤتة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_42, 'أي واقعة كانت السبب المباشر في التحرك نحو فتح مكة ضمن سياق نقض الحديبية في كتب السيرة؟', '["منع قافلة المسلمين من المرور إلى الشام","استيلاء ثقيف على هدي عمرة القضاء","اعتداء بني بكر، حلفاء قريش، على خزاعة حليفة المسلمين مع إعانة من قريش","نقض يهود خيبر عهدًا عُقد بعد الفتح"]'::jsonb, 2, 40, 16, 'multi', 'دخلت خزاعة في حلف النبي ﷺ، ودخل بنو بكر في حلف قريش. اعتدى بنو بكر على خزاعة وأعانتهم عناصر من قريش، فعدّ ذلك نقضًا للعهد واستنصرت خزاعة، فتهيأ المسلمون لفتح مكة. هذا التفصيل من روايات السيرة والمغازي المشهورة.', 'فتح مكة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_42, 'ما القرار الذي اتخذه النبي ﷺ في غنائم حنين تجاه المؤلفة قلوبهم، وكان سببًا في حديثه المؤثر مع الأنصار؟', '["ساوى بين جميع المقاتلين من غير أي عطاء زائد","خص الأنصار بجميع السبي وترك الأموال للمهاجرين","أعطى حديثي العهد بالإسلام وكبراء قريش عطاءً وافرًا للتأليف","أعاد الغنائم كلها إلى هوازن قبل مجيء وفدهم"]'::jsonb, 2, 40, 17, 'multi', 'أعطى النبي ﷺ رجالًا من المؤلفة قلوبهم عطاءً كبيرًا من غنائم حنين، فوجد بعض الأنصار في أنفسهم. جمعهم وبيّن مقصد التأليف، ورضوا بأن يرجع الناس بالشاة والبعير ويرجعوا هم برسول الله ﷺ إلى رحالهم.', 'غزوة حنين');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_42, 'في قصة كعب بن مالك، ما الذي ميّز تخلفه عن تبوك عن أعذار المنافقين عند عودة النبي ﷺ؟', '["قدم وثيقة مرض فقبلت بلا سؤال","صدق واعترف بأنه لم يكن له عذر مع قدرته، ولم يحلف كذبًا","كان مأمورًا بالبقاء لحراسة المدينة","لحق بالجيش قبل وصوله إلى تبوك"]'::jsonb, 1, 40, 18, 'multi', 'اختار كعب الصدق، فأقر بأنه كان قويًا موسرًا ولا عذر له، بينما اعتذر المتخلفون بأعذار وحلفوا. أُرجئ أمره وصاحبيه وقوطعوا خمسين ليلة، ثم نزلت توبتهم؛ فمحور القصة أخلاقي وتاريخي هو نجاة الصدق بعد الشدة.', 'غزوة تبوك');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_42, 'أي منشأة أمر القرآن النبي ﷺ ألا يقوم فيها، وكشف أن بناءها اتخذ للإضرار والتفريق بين المؤمنين في سياق العودة من تبوك؟', '["مسجد الضرار","مسجد قباء","مسجد القبلتين","المسجد النبوي"]'::jsonb, 0, 35, 19, 'multi', 'وصفت سورة التوبة مسجد الضرار بأنه اتُّخذ ضرارًا وكفرًا وتفريقًا بين المؤمنين وإرصادًا لمن حارب الله ورسوله، وأمرت النبي ﷺ ألا يقوم فيه أبدًا، وقابلته بمسجد أُسس على التقوى.', 'غزوة تبوك وما بعدها');
  END IF;
END $$;



DO $$
DECLARE
  v_lib_id_43 uuid;
BEGIN
  SELECT id INTO v_lib_id_43 FROM quizzes WHERE title = 'علوم القرآن، المصطلحات والرجال' LIMIT 1;
  IF v_lib_id_43 IS NULL THEN
    INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
    VALUES ('علوم القرآن، المصطلحات والرجال', 'إسلاميات', '', 'high', 'ar', true)
    RETURNING id INTO v_lib_id_43;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'وفق التعريف الاصطلاحي المشهور المبني على زمن الهجرة، كيف يُميَّز المكي من المدني؟', '["المكي ما نزل داخل مكة فقط، والمدني ما نزل داخل المدينة فقط","المكي ما خوطب به أهل مكة، والمدني ما خوطب به أهل المدينة","المكي ما نزل قبل الهجرة، والمدني ما نزل بعدها ولو كان مكان النزول خارج المدينة","المكي كل سورة قصيرة، والمدني كل سورة طويلة"]'::jsonb, 2, 35, 0, 'multi', 'أشهر الضوابط وأضبطها اعتبار الزمن: ما نزل قبل الهجرة مكي، وما نزل بعدها مدني، ولو نزل في مكة عام الفتح أو في سفر. أما ضابطا المكان والمخاطَبين فمذكوران عند العلماء لكنهما لا يستوعبان جميع المواضع بالقدر نفسه.', 'المكي والمدني');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'ما الفرق الأدق بين «سبب النزول» وبين مجرد وقوع حادثة في زمن نزول آية؟', '["كل حادثة سبقت نزول الآية تعد سببًا لها","سبب النزول هو المعنى اللغوي المستنبط من الآية","سبب النزول حادثة أو سؤال نزلت الآية عقبه متحدثة عنه، ولا تكفي المعاصرة الزمنية وحدها لإثبات السببية","لا يثبت سبب النزول إلا إذا ذُكر اسم السورة في الرواية"]'::jsonb, 2, 40, 1, 'multi', 'عرّف المحققون سبب النزول بما نزلت الآية أو الآيات متحدثة عنه أيام وقوعه، كحادثة أو سؤال. أما الأخبار التاريخية التي تسبق النص أو تعاصره من غير دلالة على التعقيب والارتباط فلا تصبح أسباب نزول بمجرد التزامن.', 'أسباب النزول');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'عند الأصوليين والمفسرين، ما المقصود بقاعدة «العبرة بعموم اللفظ لا بخصوص السبب»؟', '["أن الحكم يتناول ما يشمله اللفظ العام، ولا يُحصر في الواقعة التي كانت سبب النزول ما لم يقم مخصِّص","أن معرفة سبب النزول لا قيمة لها في التفسير","أن كل لفظ خاص يُحوَّل إلى عام","أن الرواية المتأخرة تنسخ سبب النزول"]'::jsonb, 0, 40, 2, 'multi', 'خصوص الواقعة يفسر السياق، لكنه لا يقصر دلالة صيغة العموم عليها؛ فيمتد الحكم إلى أفراد اللفظ العام ما لم يرد دليل تخصيص. ولا تعني القاعدة إهمال السبب، إذ قد يعين على فهم المراد ودفع الإشكال.', 'أصول التفسير');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'أي وصف يميز «القراءة» عن «الرواية» في اصطلاح أهل القراءات؟', '["القراءة خاصة بالرسم، والرواية خاصة بالتفسير","القراءة ما نُسب إلى إمام قارئ، والرواية ما نُسب إلى راوٍ عنه، والطريق ما نُسب إلى الآخذ عن الراوي فمن دونه","الرواية أعلى رتبة من القراءة وتشمل جميع القراء","القراءة اجتهاد نحوي حديث، والرواية نقل قديم"]'::jsonb, 1, 40, 3, 'multi', 'في بناء أسانيد هذا الفن تنسب القراءة إلى الإمام، كقراءة نافع، والرواية إلى أحد رواته، كرواية ورش عن نافع، والطريق إلى من أخذ عن الراوي أو عن أصحابه. هذا تصنيف لسلسلة الأداء لا لدرجات صحة مستقلة بذاتها.', 'مصطلح القراءات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'أي عالم اشتهر بأنه أول من أفرد القراءات السبع في مصنف جمع فيه قراء الأمصار السبعة؟', '["أبو بكر ابن مجاهد","أبو عمرو الداني","ابن الجزري","مكي بن أبي طالب"]'::jsonb, 0, 35, 4, 'multi', 'صنف أبو بكر أحمد بن موسى ابن مجاهد المتوفى سنة 324هـ كتاب «السبعة في القراءات»، فاشتهر باختيار أئمة سبعة من قراء الأمصار. هذا الاختيار العلمي المتأخر لا يعني أن القراءات السبع هي نفسها الأحرف السبعة الواردة في الحديث.', 'رجال القراءات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'ما الأثر العلمي الأشهر لمنظومة «حرز الأماني ووجه التهاني» للشاطبي؟', '["جمع القراءات الأربع عشرة لأول مرة","شرح رسم المصحف دون مسائل الأداء","حصر أسباب النزول في الأحاديث المرفوعة","نظم أصول وفرش القراءات السبع اعتمادًا على كتاب التيسير للداني مع زيادات"]'::jsonb, 3, 40, 5, 'multi', 'قصيدة الشاطبية نظمت مادة «التيسير في القراءات السبع» لأبي عمرو الداني وأضافت مسائل، وصارت متنًا محوريًا في تدريس السبع. أما القراءات العشر فاشتهر في نظمها لاحقًا «طيبة النشر» لابن الجزري.', 'كتب القراءات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'أي كتاب يُنسب إلى بدر الدين الزركشي ويعد من أوسع المصنفات الجامعة المبكرة في أنواع علوم القرآن؟', '["الإتقان في علوم القرآن","مناهل العرفان","الزيادة والإحسان","البرهان في علوم القرآن"]'::jsonb, 3, 30, 6, 'multi', 'ألّف بدر الدين محمد بن عبد الله الزركشي المتوفى سنة 794هـ «البرهان في علوم القرآن». أما «الإتقان» فللسيوطي، و«مناهل العرفان» للزرقاني، و«الزيادة والإحسان» لابن عقيلة المكي.', 'مصنفات علوم القرآن');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'ما المقصود بـ«الرسم العثماني» في علوم المصحف؟', '["نوع الخط الكوفي الذي اخترعه عثمان بن عفان بنفسه","هيئة كتابة كلمات المصاحف التي نُسخت في خلافة عثمان، بما لها من ظواهر حذف وزيادة وبدل وفصل ووصل","علامات الحركات والنقط التي أضيفت إلى المصحف لاحقًا","نسخة واحدة بخط عثمان محفوظة باتفاق المؤرخين"]'::jsonb, 1, 40, 7, 'multi', 'الرسم العثماني اصطلاح في هجاء المصاحف المنسوخة في عهد عثمان، لا اسم نوع خط ولا الضبط بالشكل والنقط. وتبحث كتبه ظواهر مثل الحذف والزيادة والهمز والبدل والفصل والوصل، مع فروق محدودة بين المصاحف المرسلة للأمصار.', 'رسم المصحف');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'في اصطلاح الوقف والابتداء، ما «الوقف اللازم» عند السجاوندي في الجملة؟', '["موضع يحرم الوقف عليه باتفاق","نهاية كل آية بلا استثناء","موضع يُلزم الوقف عليه اصطلاحًا لأن الوصل قد يوهم معنى غير مراد، لا بمعنى أن تاركه يأثم شرعًا","وقف اضطراري لانقطاع النفس فقط"]'::jsonb, 2, 40, 8, 'multi', 'علامة الوقف اللازم عند السجاوندي وما بُني عليها من اصطلاحات المصاحف تفيد شدة الحاجة إلى الفصل صونًا للمعنى من إيهام، و«اللُّزوم» هنا فني لا حكم تكليفي يوجب الإثم على كل واصل.', 'الوقف والابتداء');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'أي مؤلف ارتبط اسمه بكتاب «أسباب النزول» الذي صار عمدة مبكرة في بابه؟', '["أبو عبيد القاسم بن سلام","علي بن أحمد الواحدي النيسابوري","أبو جعفر النحاس","علم الدين السخاوي"]'::jsonb, 1, 30, 9, 'multi', 'ألّف المفسر الشافعي علي بن أحمد الواحدي المتوفى سنة 468هـ كتاب «أسباب النزول». والاستفادة منه لا تُغني عن نقد أسانيد الروايات؛ فجمع الخبر في كتاب موضوعي لا يحكم تلقائيًا بصحته.', 'رجال علوم القرآن');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'أي تركيب يعبّر عن أركان قبول القراءة عند ابن الجزري في عبارته المشهورة، مع ملاحظة أنه قال «وجه نحو» لا أفصح الوجوه فقط؟', '["شهرة القارئ، وموافقة لهجة قريش وحدها، ووجودها في مصحف المدينة فقط","صحة السند، وموافقة العربية ولو بوجه، وموافقة أحد المصاحف العثمانية ولو احتمالًا","موافقة القياس النحوي الأشهر، وكثرة الرواة، وترتيب السور","صحة المعنى، وقدم المخطوط، وإجماع النحاة"]'::jsonb, 1, 50, 10, 'multi', 'قرر ابن الجزري أن القراءة المقبولة توافق وجهًا من العربية، وتوافق رسم أحد المصاحف العثمانية ولو احتمالًا، ويصح سندها؛ ووصفها حينئذ بالصحيحة التي لا يجوز ردها. لا يشترط أن يكون الوجه النحوي هو الأشهر ولا أن يطابق الرسم الصريح وحده.', 'أصول القراءات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'لماذا لا يصح جعل «القراءات السبع» مرادفًا لـ«الأحرف السبعة»؟', '["لأن الأحرف السبعة سبع سور، والقراءات السبع سبعة أجزاء","لأن القراءات السبع ظهرت قبل نزول الحديث","لأن كل حرف من الأحرف منسوب حصرًا إلى قارئ من السبعة","لأن الأحرف السبعة وردت في الحديث واختلف في تفسيرها، أما تخصيص سبعة قراء فاختيار تدويني لابن مجاهد في القرن الرابع"]'::jsonb, 3, 50, 11, 'multi', 'حديث نزول القرآن على سبعة أحرف سابق لتدوين القراءات، ومعنى الأحرف نفسها محل أقوال كثيرة. أما السبعة القراء فجمعهم ابن مجاهد لاشتهار قراءتهم في أمصار معينة؛ والتوافق في العدد لا يثبت التطابق في المفهوم.', 'الأحرف والقراءات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'في رواية جمع أبي بكر للمصحف في صحيح البخاري، ما المهمة التي كُلِّف بها زيد بن ثابت بعد وقعة اليمامة؟', '["تتبّع القرآن وجمعه من العُسُب واللخاف وصدور الرجال في صحف","إلزام الأمصار بقراءة قارئ واحد دون كتابة","إضافة نقط الإعجام والحركات إلى المصحف","ترتيب السور بحسب تاريخ النزول"]'::jsonb, 0, 45, 12, 'multi', 'يروي البخاري أن أبا بكر، بإشارة عمر بعد مقتل القراء باليمامة، كلّف زيدًا بتتبع القرآن وجمعه، فكانت الصحف عند أبي بكر ثم عمر ثم حفصة. أما توحيد المصاحف وإرسال النسخ إلى الأمصار فمرحلة عثمانية لاحقة.', 'جمع القرآن');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'ما الفارق الرئيس بين جمع أبي بكر وجمع عثمان كما تصفه الروايات المشهورة؟', '["جمع أبي بكر رتّب الآيات، وجمع عثمان أضاف سورًا جديدة","جمع أبي بكر كان بلا كتابة، وجمع عثمان كان أول كتابة للقرآن","جمع أبي بكر حفظ النص في صحف بعد اليمامة، وجمع عثمان نسخ مصاحف معيارية من الصحف وإرسالها للأمصار عند اختلاف القراءة","لم تكن صحف أبي بكر مصدرًا للجنة عثمان"]'::jsonb, 2, 50, 13, 'multi', 'الدافع المباشر للجمع البكري كان خشية ذهاب شيء بموت القراء، فجمعت المادة في صحف. وفي عهد عثمان استُعيرت صحف حفصة وشكلت لجنة لنسخ مصاحف تُرسل إلى الأقاليم بهدف الحد من التنازع في وجوه القراءة، ثم رُدت الصحف إلى حفصة.', 'جمع المصحف');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'في خبر اللجنة العثمانية، ماذا كان توجيه عثمان عند اختلاف زيد بن ثابت مع الثلاثة القرشيين في شيء من القرآن؟', '["أن يتركوا الموضع بلا كتابة","أن يعتمدوا لهجة زيد المدنية في كل حال","أن يختاروا الرسم الأكثر موافقة للشعر الجاهلي","أن يكتبوه بلسان قريش، معللًا بأنه نزل بلسانهم"]'::jsonb, 3, 45, 14, 'multi', 'نص خبر أنس في البخاري على قول عثمان للرهط القرشيين وزيد: إذا اختلفتم أنتم وزيد في شيء فاكتبوه بلسان قريش فإنه نزل بلسانهم. وهو توجيه للجنة النسخ في سياق محدد، لا دعوى أن جميع التنوع العربي في الأداء أُلغي لغويًا.', 'المصحف العثماني');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'إذا صح سببان لنزول آية واحدة وكان زمنهما متقاربًا، فما المسلك الذي يذكره علماء أسباب النزول بدل إسقاط إحدى الروايتين بلا دليل؟', '["الحكم آليًا بأن الرواية الأقصر ناسخة للأطول","حمل الآية على تعدد الأسباب مع نزول واحد إذا أمكن الجمع","رفض الروايتين لأن للآية سببًا واحدًا بالضرورة","ترجيح الرواية التي يرويها مفسر متأخر دائمًا"]'::jsonb, 1, 50, 15, 'multi', 'عند صحة الروايتين وتقارب الواقعتين يمكن أن تتعدد الأسباب وينزل النص عقبها جميعًا، فلا تعارض حقيقي. أما إن تباعد الزمن وتعذر الجمع فقد يبحث العلماء احتمال تكرر النزول أو يرجحون بحسب صيغ الرواية والأسانيد والقرائن.', 'قواعد أسباب النزول');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'أي عبارة أدق في التفريق بين «النسخ» و«التخصيص» في الاستعمال الأصولي المستقر؟', '["النسخ بيان المجمل، والتخصيص حذف ألفاظ الآية","النسخ رفع حكم شرعي بدليل شرعي متراخٍ، والتخصيص قصر العام على بعض أفراده ولا يستلزم رفع أصل الحكم","كلاهما يعني محو النص من المصحف","التخصيص لا يقع إلا زمنيًا بعد العمل بالعام"]'::jsonb, 1, 50, 16, 'multi', 'يفترق الاصطلاحان بأن النسخ يتضمن رفع حكم سابق بخطاب متراخٍ، بينما يبقي التخصيص حكم العام في بعض الأفراد ويخرج بعضها بدليل. وقد كان لفظ النسخ عند بعض السلف أوسع، فيطلق أحيانًا على البيان والتخصيص؛ لذلك يلزم الانتباه إلى اصطلاح القائل.', 'الناسخ والمنسوخ');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'أي عالم ألّف كتاب «الناسخ والمنسوخ» واشتهر أيضًا بكتاب «إعراب القرآن»؟', '["أبو عبيد القاسم بن سلام","ابن الأنباري","مكي بن أبي طالب","أبو جعفر النحاس"]'::jsonb, 3, 40, 17, 'multi', 'أبو جعفر أحمد بن محمد النحاس المتوفى سنة 338هـ صاحب «الناسخ والمنسوخ» و«إعراب القرآن». وقد يناقش في كتاب النسخ دعاوى المتقدمين ولا تكون كل نسبة للنسخ فيه موضع اتفاق بين العلماء.', 'رجال ومصنفات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'كيف عالج ابن الجزري القراءات الثلاث المتممة للعشر بالنسبة إلى سبع ابن مجاهد؟', '["أثبت قراءات أبي جعفر ويعقوب وخلف مع السبعة ضمن منظومة القراءات العشر","أضاف الحسن البصري والأعمش وابن محيصن إلى السبعة","استبدل نافعًا وعاصمًا بثلاثة قراء","عدّ كل قراءة خارج السبع شاذة بلا تفصيل"]'::jsonb, 0, 45, 18, 'multi', 'العشرة المشهورون هم السبعة الذين جمعهم ابن مجاهد، ويضاف إليهم أبو جعفر المدني ويعقوب الحضرمي وخلف العاشر. أما الحسن والأعمش وابن محيصن واليزيدي فتذكر قراءاتهم عادة ضمن الأربع الزائدة على العشر في كتب القراءات الأربع عشرة.', 'القراء العشرة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'ما موضوع كتاب أبي عمرو الداني «التيسير» مقارنة بكتابه «المقنع»؟', '["التيسير في الناسخ والمنسوخ، والمقنع في أسباب النزول","التيسير في عد الآي، والمقنع في غريب القرآن فقط","التيسير في القراءات السبع، والمقنع في رسم مصاحف الأمصار","كلاهما شرح للقراءات العشر بالموضوع نفسه"]'::jsonb, 2, 45, 19, 'multi', '«التيسير في القراءات السبع» أصل مهم في نقل مذاهب القراء السبعة، ونظمه الشاطبي. أما «المقنع في معرفة مرسوم مصاحف أهل الأمصار» فيبحث هيئة كتابة المصاحف واختلاف رسومها، فهما فرعان متمايزان من علوم القرآن.', 'مصنفات الداني');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'في علم عدّ الآي، لماذا قد تختلف أعداد آيات سورة بين مدرستين مع اتفاقهما على النص القرآني نفسه؟', '["لاختلافهما في عد بعض مواضع الفصل رأس آية أو وصلها بما بعدها، لا لاختلاف ألفاظ القرآن","لأن كل مدرسة تضيف آيات تفسيرية إلى النص","لأن بعض المدارس تحذف البسملة من المصحف كله","لأن ترتيب كلمات السورة يتغير بين مدارس العد"]'::jsonb, 0, 50, 20, 'multi', 'مدارس العد المدني والمكي والكوفي والبصري والشامي قد تختلف في مواضع الفواصل: أهي رأس آية مستقل أم متصلة بما بعدها، مع بقاء الكلمات وترتيبها واحدًا. لذلك لا يصح تحويل اختلاف العدد إلى دعوى اختلاف في نص القرآن.', 'عد الآي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'أي وصف أدق لـ«فواصل الآي» في اصطلاح علماء القرآن؟', '["علامات الأحزاب والأجزاء التي وضعها النساخ","الكلمات الواقعة في أواخر الآيات، وقد تتشابه صوتيًا مع السجع من غير أن يلزم تسميتها سجعًا","الحروف المقطعة في أوائل السور فقط","كل موضع يجوز للقارئ أن يتنفس عنده"]'::jsonb, 1, 45, 21, 'multi', 'الفاصلة كلمة آخر الآية، ونسبتها إلى الآية تشبه نسبة القافية إلى البيت مع فروق الجنس الأدبي. ناقش العلماء إطلاق «السجع» على القرآن؛ فمنهم من منعه ومنهم من أجاز الوصف بمعنى التناسب، لذا لا تجعل المسألة محل إجماع اصطلاحي.', 'فواصل الآي');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'ما الفرق بين «غريب القرآن» و«مشكل القرآن» بوصفهما حقلين في التأليف؟', '["الغريب خاص بالقراءات المتواترة، والمشكل خاص بالقراءات الشاذة","الغريب يبحث ترتيب السور، والمشكل يبحث عد الآي","هما اسمان مترادفان تمامًا لكل كتب التفسير","الغريب يشرح الألفاظ البعيدة عن التداول أو الخفية، والمشكل يعالج ما يوهم تعارضًا أو إشكالًا دلاليًا ونحوه"]'::jsonb, 3, 50, 22, 'multi', 'كتب الغريب تتجه أساسًا إلى بيان المفردات المحتاجة إلى تفسير لغوي، مثل «مجاز القرآن» وكتب غريب القرآن. وكتب المشكل تدفع وجوه الالتباس، كتوهم التعارض أو الإشكال في التعبير؛ وقد تتداخل المادة بين الحقلين من غير أن يتطابقا.', 'مصطلحات التفسير');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'أي عبارة تضبط مصطلحي «أصول القراءة» و«فرش الحروف» في كتب القراءات؟', '["الأصول قواعد مطردة تتكرر كالإدغام والمد، والفرش كلمات جزئية مختلف فيها تُذكر في مواضع السور","الأصول هي القراءات السبع، والفرش هي الثلاث المتممة","الأصول خاصة بالرسم، والفرش خاص بعد الآي","الفرش أحكام التجويد المتفق عليها فقط"]'::jsonb, 0, 50, 23, 'multi', 'يفصل المصنفون عادة بين القواعد الكلية المتكررة، مثل أحكام الهمز والإدغام والمد والإمالة، وبين «الفرش»؛ أي ألفاظ بعينها تتوزع في السور ويختلف القراء في أدائها. وقد تختلف طريقة المصنف في إلحاق بعض المسائل بأحد القسمين.', 'منهج كتب القراءات');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_43, 'من صاحب «جمال القراء وكمال الإقراء»، وما صلته العلمية بالشاطبي؟', '["أبو عمرو الداني، وكان تلميذًا مباشرًا لابن الجزري","ابن مجاهد، وكان شارحًا لطيبة النشر","علم الدين السخاوي، وكان من أبرز تلاميذ الشاطبي وشارحي قصيدته","الزركشي، وكان راويًا عن نافع"]'::jsonb, 2, 45, 24, 'multi', 'ألّف علم الدين علي بن محمد السخاوي المتوفى سنة 643هـ «جمال القراء وكمال الإقراء». أخذ عن القاسم الشاطبي ولازمه، وشرح «حرز الأماني» في كتاب «فتح الوصيد»، فكان حلقة مهمة في نقل المدرسة الشاطبية.', 'رجال الإقراء');
  END IF;
END $$;

